export const SOURCES = {"TBOX":["tbox/app.ttl","tbox/perma-vegetation.ttl","tbox/perma-food.ttl","tbox/perma-habitat.ttl","tbox/perma-learning.ttl"],"CONCEPTS":["tbox/pt-concepts.ttl","tbox/perma-vegetation-concepts.ttl","tbox/perma-food-concepts.ttl","tbox/perma-habitat-concepts.ttl","tbox/perma-learning-concepts.ttl"],"LIBRARY":["abox/library/crops.ttl"],"SHAPES":["shapes/pt-shapes.ttl","shapes/perma-vegetation-shapes.ttl","shapes/perma-food-shapes.ttl","shapes/perma-habitat-shapes.ttl","shapes/perma-learning-shapes.ttl"]};
export const TBOX = "@prefix app:     <https://permtek-5.digitalhome.cloud/ontology#> .\n@prefix owl:     <http://www.w3.org/2002/07/owl#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix schema:  <https://schema.org/> .\n\n# ============================================================\n# The T-Box, v0.1: a PLACEHOLDER to replace with your domain.\n#\n# A thin layer over standard vocabularies. Define only what they do not\n# have, and say how the standards are used here. Each space keeps an A-Box\n# (instances) of this vocabulary, synced with the tenant's edges (ADR-0007).\n#\n# Labels: English is the master and is required (shapes/app-shapes.ttl);\n# German and French are given for everything a person sees.\n#\n# After a change: node backend/scripts/sync-ontology.mjs, so the Lambdas\n# validate against the same file.\n# ============================================================\n\n<https://permtek-5.digitalhome.cloud/ontology>\n    a owl:Ontology ;\n    rdfs:label \"Template ontology\"@en , \"Vorlagen-Ontologie\"@de , \"Ontologie du modèle\"@fr ;\n    dcterms:description \"A placeholder: things a tenant knows about, of a type from a concept scheme, in a place.\"@en ;\n    owl:versionInfo \"0.1.0\" .\n\napp:Thing a owl:Class ;\n    rdfs:subClassOf schema:Thing ;\n    rdfs:label \"Thing\"@en , \"Ding\"@de , \"Chose\"@fr ;\n    rdfs:comment \"Something the tenant knows about. Replace with your domain's classes.\"@en .\n\napp:Place a owl:Class ;\n    rdfs:subClassOf schema:Place ;\n    rdfs:label \"Place\"@en , \"Ort\"@de , \"Lieu\"@fr .\n\napp:thingType a owl:ObjectProperty ;\n    rdfs:domain app:Thing ;\n    rdfs:label \"type\"@en , \"Art\"@de , \"type\"@fr ;\n    rdfs:comment \"A concept from app:ThingTypes (tbox/app-concepts.ttl): new types are data, not code.\"@en .\n\napp:locatedIn a owl:ObjectProperty ;\n    rdfs:range app:Place ;\n    rdfs:label \"located in\"@en , \"befindet sich in\"@de , \"se trouve dans\"@fr .\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix owl:     <http://www.w3.org/2002/07/owl#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix geo:     <http://www.opengis.net/ont/geosparql#> .\n@prefix sosa:    <http://www.w3.org/ns/sosa/> .\n@prefix dwc:     <http://rs.tdwg.org/dwc/terms/> .\n\n# ============================================================\n# perma-core, vegetation module, v0.1\n#\n# The vegetation map of a site: what grows where, how tall, and whether it\n# casts a canopy. A sidecar to perma-core (ADR 0012): standard vocabularies\n# stay read-only (GeoSPARQL for geometry, SOSA for what is observed, Darwin\n# Core for taxa); this file adds only what they lack.\n#\n# Two kinds of unit, both mapped by people first and later suggested by the\n# rovers' observations (docs/workflow.md, stages 2 and 4):\n#   - a patch: an area with one dominant vegetation class (meadow, bramble ...)\n#   - a single plant drawn on the map (an oak, the walnut): perma:Plant from\n#     perma-core is also a perma:VegetationUnit\n#\n# Types are data: the classes of vegetation are SKOS concepts in\n# perma-vegetation-concepts.ttl, so a new one needs no schema change.\n# How a class behaves for a rover (drive cost, GNSS under canopy) is a\n# simulation parameter and lives in the twin, not here.\n#\n# Namespace: provisional (build plan, open decision \"Namespaces\"). It must\n# match perma-core's when that file joins this folder.\n# Labels: English is the master; German and French are given.\n# ============================================================\n\n<https://permaculture.digitalhome.cloud/ontology/vegetation>\n    a owl:Ontology ;\n    rdfs:label \"perma-core: vegetation\"@en , \"perma-core: Vegetation\"@de , \"perma-core : végétation\"@fr ;\n    dcterms:description \"The vegetation map of a permaculture site: patches and single plants, their class, height, canopy and status.\"@en ;\n    owl:versionInfo \"0.1.0\" .\n\n# ------------------------------------------------------------ classes\n\nperma:VegetationUnit a owl:Class ;\n    rdfs:subClassOf geo:Feature , sosa:FeatureOfInterest ;\n    rdfs:label \"Vegetation unit\"@en , \"Vegetationseinheit\"@de , \"Unité de végétation\"@fr ;\n    rdfs:comment \"Something growing on the site that is drawn on the vegetation map: a patch or a single plant. It has a geometry, a vegetation class and a status, and is what observations of vegetation are about.\"@en .\n\nperma:VegetationPatch a owl:Class ;\n    rdfs:subClassOf perma:VegetationUnit ;\n    rdfs:label \"Vegetation patch\"@en , \"Vegetationsfläche\"@de , \"Parcelle de végétation\"@fr ;\n    rdfs:comment \"An area with one dominant vegetation class, e.g. a meadow, a bramble thicket, a hedge.\"@en .\n\nperma:Plant a owl:Class ;\n    rdfs:subClassOf perma:VegetationUnit ;\n    rdfs:label \"Plant\"@en , \"Pflanze\"@de , \"Plante\"@fr ;\n    rdfs:comment \"Defined in perma-core as a dwc:Organism followed over years. Stated here only as a vegetation unit, so a single tree can be drawn on the vegetation map.\"@en .\n\n# ------------------------------------------------------------ properties\n\nperma:vegetationClass a owl:ObjectProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"vegetation class\"@en , \"Vegetationsklasse\"@de , \"classe de végétation\"@fr ;\n    rdfs:comment \"One concept from perma:VegetationClasses.\"@en .\n\nperma:vegetationStatus a owl:ObjectProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"vegetation status\"@en , \"Vegetationsstatus\"@de , \"statut de la végétation\"@fr ;\n    rdfs:comment \"One concept from perma:VegetationStatuses: there already, planted by us, or only planned.\"@en .\n\nperma:mapStatus a owl:ObjectProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"map status\"@en , \"Kartenstatus\"@de , \"statut sur la carte\"@fr ;\n    rdfs:comment \"How sure the map is: one concept from perma:MapStatuses. A unit traced from a plan or suggested by a rover stays ToConfirm until a person has looked.\"@en .\n\nperma:heightM a owl:DatatypeProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range xsd:decimal ;\n    rdfs:label \"height (m)\"@en , \"Höhe (m)\"@de , \"hauteur (m)\"@fr ;\n    rdfs:comment \"Typical height of the vegetation, metres.\"@en .\n\nperma:hasCanopy a owl:DatatypeProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range xsd:boolean ;\n    rdfs:label \"has canopy\"@en , \"hat ein Kronendach\"@de , \"a une canopée\"@fr ;\n    rdfs:comment \"True when the unit closes over the ground: it shades the soil and degrades satellite positioning beneath it.\"@en .\n\nperma:canopyRadiusM a owl:DatatypeProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range xsd:decimal ;\n    rdfs:label \"canopy radius (m)\"@en , \"Kronenradius (m)\"@de , \"rayon de la couronne (m)\"@fr .\n\nperma:dominantTaxon a owl:ObjectProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range dwc:Taxon ;\n    rdfs:label \"dominant taxon\"@en , \"vorherrschendes Taxon\"@de , \"taxon dominant\"@fr ;\n    rdfs:comment \"The taxon that makes up most of the unit, referenced by its GBIF or TAXREF IRI (perma-bio), never copied in.\"@en .\n\nperma:mapSource a owl:DatatypeProperty ;\n    rdfs:domain perma:VegetationUnit ;\n    rdfs:range xsd:string ;\n    rdfs:label \"map source\"@en , \"Kartenquelle\"@de , \"source cartographique\"@fr ;\n    rdfs:comment \"Where the outline comes from: a plan, an aerial photo, a walk, a rover's observation.\"@en .\n\n# perma:observedInZone (perma-core) links a unit to its zone.\n# Geometry: geo:hasGeometry / geo:asWKT, in the site's local frame (metres,\n# x east, y north); the georeference lives in the private space (ADR 0009).\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix owl:     <http://www.w3.org/2002/07/owl#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix schema:  <https://schema.org/> .\n@prefix dwc:     <http://rs.tdwg.org/dwc/terms/> .\n\n# ============================================================\n# perma-core, food module, v0.1: crops, their seasons on a site, recipes.\n#\n# Three layers, kept apart because they are shared differently:\n#   - the CROP LIBRARY (perma:Crop): what a crop is, which parts we eat and\n#     the ways each can be kept (fresh, cellar, dried, frozen ...) and for how\n#     long. The same for every project (a global library).\n#   - the SITE CALENDAR (perma:SeasonWindow): when to sow, plant out and\n#     harvest on ONE site. Climate, altitude and exposure make it differ\n#     between projects, so it lives in the site's A-Box.\n#   - RECIPES (schema:Recipe): ingredients linked to crops and parts, so a\n#     recipe can be checked against a site's calendar (\"when can I make this\n#     from my garden, and what do I still have to buy?\").\n#\n# schema.org already has Recipe, recipeIngredient (text) and\n# recipeInstructions; this file adds only the links to crops and seasons.\n# Namespace provisional, as in perma-vegetation.ttl.\n# ============================================================\n\n<https://permaculture.digitalhome.cloud/ontology/food>\n    a owl:Ontology ;\n    rdfs:label \"perma-core: food\"@en , \"perma-core: Lebensmittel\"@de , \"perma-core : alimentation\"@fr ;\n    dcterms:description \"Crops, their seasons on a site, and recipes that use them.\"@en ;\n    owl:versionInfo \"0.1.0\" .\n\n# ------------------------------------------------------------ crop library\n\nperma:Crop a owl:Class ;\n    rdfs:label \"Crop\"@en , \"Kulturpflanze\"@de , \"Culture\"@fr ;\n    rdfs:comment \"A kind of cultivated plant as gardeners and cooks name it (courgette, onion), linked to its taxon. One entry in the shared crop library.\"@en .\n\nperma:taxon a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ;\n    rdfs:range dwc:Taxon ;\n    rdfs:label \"taxon\"@en , \"Taxon\"@de , \"taxon\"@fr ;\n    rdfs:comment \"The crop's taxon, by GBIF or TAXREF IRI (perma-bio); dwc:scientificName gives the name until then.\"@en .\n\nperma:yields a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ;\n    rdfs:range perma:HarvestPart ;\n    rdfs:label \"yields\"@en , \"liefert\"@de , \"produit\"@fr .\n\nperma:HarvestPart a owl:Class ;\n    rdfs:label \"Harvested part\"@en , \"Erntegut\"@de , \"Partie récoltée\"@fr ;\n    rdfs:comment \"A part of a crop that is harvested and used (the fruit of the courgette, the seed of mustard), with the ways it can be kept.\"@en .\n\nperma:part a owl:ObjectProperty ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"part\"@en , \"Pflanzenteil\"@de , \"partie\"@fr ;\n    rdfs:comment \"One concept from perma:PlantParts.\"@en .\n\nperma:keeps a owl:ObjectProperty ;\n    rdfs:domain perma:HarvestPart ;\n    rdfs:range perma:KeepingWay ;\n    rdfs:label \"keeps\"@en , \"hält sich\"@de , \"se conserve\"@fr ;\n    rdfs:comment \"One way the part can be kept after the harvest, with how long. Dill leaves: fresh a few days, dried a year.\"@en .\n\nperma:KeepingWay a owl:Class ;\n    rdfs:label \"Way of keeping\"@en , \"Aufbewahrungsart\"@de , \"Mode de conservation\"@fr ;\n    rdfs:comment \"A preservation method and how many months a part keeps that way.\"@en .\n\nperma:method a owl:ObjectProperty ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"method\"@en , \"Methode\"@de , \"méthode\"@fr ;\n    rdfs:comment \"One concept from perma:PreservationMethods.\"@en .\n\nperma:storageMonths a owl:DatatypeProperty ;\n    rdfs:domain perma:KeepingWay ;\n    rdfs:range xsd:integer ;\n    rdfs:label \"keeps (months)\"@en , \"haltbar (Monate)\"@de , \"se conserve (mois)\"@fr ;\n    rdfs:comment \"How many months after the harvest the part keeps this way. 0 = only in the weeks of the harvest.\"@en .\n\n# ------------------------------------------------------------ site calendar\n\nperma:SeasonWindow a owl:Class ;\n    rdfs:label \"Season window\"@en , \"Saisonfenster\"@de , \"Fenêtre saisonnière\"@fr ;\n    rdfs:comment \"When one garden activity for one crop happens on one site: from month to month (the window may run over the new year).\"@en .\n\nperma:forCrop a owl:ObjectProperty ;\n    rdfs:domain perma:SeasonWindow ;\n    rdfs:range perma:Crop ;\n    rdfs:label \"for crop\"@en , \"für Kultur\"@de , \"pour la culture\"@fr .\n\nperma:atSite a owl:ObjectProperty ;\n    rdfs:domain perma:SeasonWindow ;\n    rdfs:label \"at site\"@en , \"am Standort\"@de , \"sur le site\"@fr ;\n    rdfs:comment \"The site (tenant) the window holds for. Another site, another calendar.\"@en .\n\nperma:activity a owl:ObjectProperty ;\n    rdfs:domain perma:SeasonWindow ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"activity\"@en , \"Tätigkeit\"@de , \"activité\"@fr ;\n    rdfs:comment \"One concept from perma:GardenActivities.\"@en .\n\nperma:fromMonth a owl:DatatypeProperty ;\n    rdfs:domain perma:SeasonWindow ; rdfs:range xsd:integer ;\n    rdfs:label \"from month\"@en , \"ab Monat\"@de , \"à partir du mois\"@fr .\n\nperma:toMonth a owl:DatatypeProperty ;\n    rdfs:domain perma:SeasonWindow ; rdfs:range xsd:integer ;\n    rdfs:label \"to month\"@en , \"bis Monat\"@de , \"jusqu'au mois\"@fr .\n\nperma:confirmation a owl:ObjectProperty ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"confirmation\"@en , \"Bestätigung\"@de , \"confirmation\"@fr ;\n    rdfs:comment \"How sure a value is: one concept from perma:MapStatuses (to confirm, confirmed, rejected). A calendar starts from general practice and is confirmed by the site's own harvest records.\"@en .\n\nperma:basis a owl:DatatypeProperty ;\n    rdfs:range xsd:string ;\n    rdfs:label \"basis\"@en , \"Grundlage\"@de , \"fondement\"@fr ;\n    rdfs:comment \"Where a value comes from: general practice for a climate, the site's own records, a seed catalogue.\"@en .\n\n# ------------------------------------------------------------ recipes\n\nperma:usesIngredient a owl:ObjectProperty ;\n    rdfs:domain schema:Recipe ;\n    rdfs:range perma:IngredientUse ;\n    rdfs:label \"uses ingredient\"@en , \"verwendet Zutat\"@de , \"utilise l'ingrédient\"@fr .\n\nperma:IngredientUse a owl:Class ;\n    rdfs:label \"Ingredient use\"@en , \"Zutatenverwendung\"@de , \"Utilisation d'ingrédient\"@fr ;\n    rdfs:comment \"One line of a recipe: its text (schema:name, as written), and when it comes from a crop, which crop and which part, and how the recipe accepts it (fresh, dried ...). A line without a crop is bought (vinegar, salt, a curry mix).\"@en .\n\nperma:crop a owl:ObjectProperty ;\n    rdfs:domain perma:IngredientUse ; rdfs:range perma:Crop ;\n    rdfs:label \"crop\"@en , \"Kultur\"@de , \"culture\"@fr .\n\nperma:acceptsMethod a owl:ObjectProperty ;\n    rdfs:domain perma:IngredientUse ; rdfs:range skos:Concept ;\n    rdfs:label \"accepts\"@en , \"akzeptiert\"@de , \"accepte\"@fr ;\n    rdfs:comment \"How the recipe takes this ingredient: fresh, dried, from the cellar ... (perma:PreservationMethods). Without it, any way the part keeps will do.\"@en .\n\nperma:preservesAs a owl:ObjectProperty ;\n    rdfs:domain schema:Recipe ; rdfs:range skos:Concept ;\n    rdfs:label \"preserves as\"@en , \"konserviert als\"@de , \"conserve sous forme de\"@fr ;\n    rdfs:comment \"When the recipe itself is a way of keeping the harvest: its method (pickled, fermented, bottled).\"@en .\n\nperma:shelfLifeDays a owl:DatatypeProperty ;\n    rdfs:domain schema:Recipe ; rdfs:range xsd:integer ;\n    rdfs:label \"keeps (days)\"@en , \"haltbar (Tage)\"@de , \"se conserve (jours)\"@fr ;\n    rdfs:comment \"How long the result keeps, as the recipe says it is stored.\"@en .\n\n# ------------------------------------------------------------ seed saving (keeping the plants)\n\nperma:seedSaving a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ; rdfs:range perma:SeedSaving ;\n    rdfs:label \"seed saving\"@en , \"Saatgutgewinnung\"@de , \"production de semences\"@fr .\n\nperma:SeedSaving a owl:Class ;\n    rdfs:label \"Seed saving\"@en , \"Saatgutgewinnung\"@de , \"Production de semences\"@fr ;\n    rdfs:comment \"How to keep a crop going from the garden: how it is propagated, its life cycle, and for seed: pollination, what it crosses with, how far to isolate it, how long the seed stays good.\"@en .\n\nperma:lifeCycle a owl:ObjectProperty ;\n    rdfs:domain perma:SeedSaving ; rdfs:range skos:Concept ;\n    rdfs:label \"life cycle\"@en , \"Lebenszyklus\"@de , \"cycle de vie\"@fr ;\n    rdfs:comment \"One concept from perma:LifeCycles: a biennial only sets seed in its second year.\"@en .\n\nperma:pollination a owl:ObjectProperty ;\n    rdfs:domain perma:SeedSaving ; rdfs:range skos:Concept ;\n    rdfs:label \"pollination\"@en , \"Bestäubung\"@de , \"pollinisation\"@fr ;\n    rdfs:comment \"One concept from perma:PollinationTypes.\"@en .\n\nperma:crossesWith a owl:DatatypeProperty ;\n    rdfs:domain perma:SeedSaving ; rdfs:range xsd:string ;\n    rdfs:label \"crosses with\"@en , \"kreuzt sich mit\"@de , \"se croise avec\"@fr ;\n    rdfs:comment \"What else in the garden or the neighbourhood the crop crosses with (usually everything of the same species).\"@en .\n\nperma:isolationM a owl:DatatypeProperty ;\n    rdfs:domain perma:SeedSaving ; rdfs:range xsd:decimal ;\n    rdfs:label \"isolation distance (m)\"@en , \"Isolationsabstand (m)\"@de , \"distance d'isolement (m)\"@fr ;\n    rdfs:comment \"Distance from other flowering plants it crosses with, for seed true to type. Bagging or hand pollination replaces it.\"@en .\n\nperma:seedViabilityYears a owl:DatatypeProperty ;\n    rdfs:domain perma:SeedSaving ; rdfs:range xsd:integer ;\n    rdfs:label \"seed stays good (years)\"@en , \"Keimfähigkeit (Jahre)\"@de , \"durée germinative (ans)\"@fr ;\n    rdfs:comment \"Years the seed keeps a useful germination rate, stored cool and dry.\"@en .\n\nperma:selfSows a owl:DatatypeProperty ;\n    rdfs:domain perma:SeedSaving ; rdfs:range xsd:boolean ;\n    rdfs:label \"self-sows\"@en , \"sät sich selbst aus\"@de , \"se ressème seul\"@fr .\n\nperma:propagation a owl:ObjectProperty ;\n    rdfs:domain perma:SeedSaving ; rdfs:range skos:Concept ;\n    rdfs:label \"propagated by\"@en , \"vermehrt durch\"@de , \"multiplié par\"@fr ;\n    rdfs:comment \"How the crop is kept going: concepts from perma:PropagationMethods. Garlic from cloves, apple by grafting (its seed does not come true).\"@en .\n\n# ------------------------------------------------------------ what a crop needs (for a calendar from the climate)\n#\n# General-practice thresholds, compared with an area's monthly normals (the\n# mean of the daily minimum, mean and maximum temperature), shifted by a\n# zone's microclimate offset. packages/core/src/calendar.ts derives sowing,\n# planting-out and harvest months from them; every derived month is \"to\n# confirm\" until the site's own records say otherwise.\n\nperma:growthForm a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ; rdfs:range skos:Concept ;\n    rdfs:label \"growth form\"@en , \"Wuchsform\"@de , \"port\"@fr ;\n    rdfs:comment \"For woody crops: perma:Tree or perma:Shrub (perma:VegetationClasses). Their calendar is typical windows, not sowing.\"@en .\n\nperma:sowMinTempC a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:decimal ;\n    rdfs:label \"sow from (mean °C)\"@en , \"Aussaat ab (Mittel °C)\"@de , \"semis à partir de (moy. °C)\"@fr ;\n    rdfs:comment \"Sow outdoors once the monthly mean temperature reaches this. Above every month's mean: start it under cover.\"@en .\n\nperma:plantOutMinNightC a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:decimal ;\n    rdfs:label \"plant out from (nights °C)\"@en , \"Auspflanzen ab (Nächte °C)\"@de , \"plantation à partir de (nuits °C)\"@fr ;\n    rdfs:comment \"For frost-tender crops: plant out once the mean daily minimum reaches this.\"@en .\n\nperma:boltAboveC a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:decimal ;\n    rdfs:label \"bolts above (max °C)\"@en , \"schießt über (Max °C)\"@de , \"monte en graines au-dessus de (max °C)\"@fr ;\n    rdfs:comment \"Do not sow in months whose mean daily maximum is above this: the crop runs to seed (lettuce, spinach, rocket).\"@en .\n\nperma:frostTender a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:boolean ;\n    rdfs:label \"frost-tender\"@en , \"frostempfindlich\"@de , \"craint le gel\"@fr .\n\nperma:daysToHarvest a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:integer ;\n    rdfs:label \"days to harvest\"@en , \"Tage bis zur Ernte\"@de , \"jours jusqu'à la récolte\"@fr ;\n    rdfs:comment \"From sowing to the first harvest, in good conditions.\"@en .\n\nperma:spacingCm a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:integer ;\n    rdfs:label \"spacing (cm)\"@en , \"Abstand (cm)\"@de , \"espacement (cm)\"@fr ;\n    rdfs:comment \"Distance between plants; in a bed it gives how many cells one plant covers.\"@en .\n\nperma:typicalWindow a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ; rdfs:range perma:TypicalWindow ;\n    rdfs:label \"typical window\"@en , \"typisches Zeitfenster\"@de , \"période habituelle\"@fr .\n\nperma:TypicalWindow a owl:Class ;\n    rdfs:label \"Typical window\"@en , \"Typisches Zeitfenster\"@de , \"Période habituelle\"@fr ;\n    rdfs:comment \"When an activity usually happens for a crop in a stated climate (perma:basis), e.g. pruning or flowering of a fruit tree. A site's own perma:SeasonWindow overrides it.\"@en .\n\n# ------------------------------------------------------------ how to sow and tend (by hand or by a gantry robot)\n\nperma:sowingDepthMm a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:integer ;\n    rdfs:label \"sowing depth (mm)\"@en , \"Saattiefe (mm)\"@de , \"profondeur de semis (mm)\"@fr ;\n    rdfs:comment \"How deep the seed goes; 0 for light germinators pressed onto the surface. A gantry's seeder uses it as its z.\"@en .\n\nperma:seedsPerPoint a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:integer ;\n    rdfs:label \"seeds per point\"@en , \"Samen je Saatstelle\"@de , \"graines par poquet\"@fr ;\n    rdfs:comment \"Seeds sown at one point; the strongest seedling is kept (thinning).\"@en .\n\nperma:germinationDays a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:integer ;\n    rdfs:label \"days to germinate\"@en , \"Keimdauer (Tage)\"@de , \"durée de levée (jours)\"@fr ;\n    rdfs:comment \"In good conditions; after this, a camera pass can check whether the point came up.\"@en .\n\nperma:waterMmPerWeek a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:decimal ;\n    rdfs:label \"water (mm per week)\"@en , \"Wasser (mm pro Woche)\"@de , \"eau (mm par semaine)\"@fr ;\n    rdfs:comment \"Rain plus watering the crop wants in its growing season; 1 mm is 1 litre per m². Shallow roof beds dry faster.\"@en .\n\n# ------------------------------------------------------------ what a crop takes from the bed and gives to it (mixed planting)\n#\n# In permaculture a bed is planted mixed, not in blocks: neighbours that take\n# different things from the soil, root at different depths, and help each\n# other. These properties say what a crop takes and gives; from them\n# packages/core/src/planting.ts suggests where each plant goes. They are\n# traditional companion-planting guidance. Evidence for single pairings is\n# mixed; every statement is \"to confirm\" by what the bed itself shows.\n\nperma:feeding a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ; rdfs:range skos:Concept ;\n    rdfs:label \"feeding\"@en , \"Nährstoffbedarf\"@de , \"besoin en nutriments\"@fr ;\n    rdfs:comment \"How much the crop takes from the soil (perma:FeedingLevels): heavy, medium or light feeder, or a soil builder that leaves it richer.\"@en .\n\nperma:rootDepth a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ; rdfs:range skos:Concept ;\n    rdfs:label \"root depth\"@en , \"Wurzeltiefe\"@de , \"profondeur d'enracinement\"@fr ;\n    rdfs:comment \"Where the crop takes water and nutrients (perma:RootDepths). Neighbours at different depths compete less.\"@en .\n\nperma:heightCm a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:integer ;\n    rdfs:label \"height (cm)\"@en , \"Höhe (cm)\"@de , \"hauteur (cm)\"@fr ;\n    rdfs:comment \"Usual height when grown; tall crops go where they do not shade low ones.\"@en .\n\nperma:gives a owl:ObjectProperty ;\n    rdfs:domain perma:Crop ; rdfs:range skos:Concept ;\n    rdfs:label \"gives\"@en , \"gibt\"@de , \"apporte\"@fr ;\n    rdfs:comment \"What the crop gives its neighbours or the soil (perma:SoilGifts): nitrogen, confusion for pests, soil cover, food for pollinators, loosened soil.\"@en .\n\nperma:goodNeighbour a owl:ObjectProperty , owl:SymmetricProperty ;\n    rdfs:domain perma:Crop ; rdfs:range perma:Crop ;\n    rdfs:label \"good neighbour of\"@en , \"guter Nachbar von\"@de , \"bon voisin de\"@fr ;\n    rdfs:comment \"Traditionally planted side by side. Stated once; it holds both ways.\"@en .\n\nperma:badNeighbour a owl:ObjectProperty , owl:SymmetricProperty ;\n    rdfs:domain perma:Crop ; rdfs:range perma:Crop ;\n    rdfs:label \"bad neighbour of\"@en , \"schlechter Nachbar von\"@de , \"mauvais voisin de\"@fr ;\n    rdfs:comment \"Traditionally kept apart. Stated once; it holds both ways.\"@en .\n\nperma:coverCrop a owl:DatatypeProperty ;\n    rdfs:domain perma:Crop ; rdfs:range xsd:boolean ;\n    rdfs:label \"cover crop\"@en , \"Gründüngung\"@de , \"engrais vert\"@fr ;\n    rdfs:comment \"Sown to cover bare soil between and after the crops, then cut and left as mulch. No bare soil: what is not planted is covered.\"@en .\n\n# ------------------------------------------------------------ plant sets: plants chosen together (docs/adr/0027)\n#\n# A plant set is a composition planned as one: \"Kitchen herbs\", \"Salad bed\",\n# \"Tomato and friends\". It names its crops and the share of the room each gets;\n# packages/core/src/planting.ts (planFromSets) turns one or more sets into a\n# mixed bed, the biggest plants first and the little ones last, and a person\n# fine-tunes it. Not \"guild\": in this app a guild is a Perma5Guild (bed and robot).\n\nperma:PlantSet a owl:Class ;\n    rdfs:label \"Plant set\"@en , \"Pflanzenset\"@de , \"Ensemble de plantes\"@fr ;\n    rdfs:comment \"Crops planned together for a surface, each with its share of the room. Traditional guidance, to confirm by what the bed shows.\"@en .\n\nperma:SetMember a owl:Class ;\n    rdfs:label \"Plant set member\"@en , \"Teil eines Pflanzensets\"@de , \"Membre d'un ensemble\"@fr ;\n    rdfs:comment \"One crop of a plant set and its share.\"@en .\n\nperma:member a owl:ObjectProperty ;\n    rdfs:domain perma:PlantSet ; rdfs:range perma:SetMember ;\n    rdfs:label \"member\"@en , \"Teil\"@de , \"membre\"@fr .\n\nperma:memberCrop a owl:ObjectProperty ;\n    rdfs:domain perma:SetMember ; rdfs:range perma:Crop ;\n    rdfs:label \"crop\"@en , \"Kultur\"@de , \"culture\"@fr .\n\nperma:share a owl:DatatypeProperty ;\n    rdfs:range xsd:decimal ;\n    rdfs:label \"share\"@en , \"Anteil\"@de , \"part\"@fr ;\n    rdfs:comment \"A relative share of the room (not of the plant count): 2 is twice the area of 1. A set member's share of its set, or a set's share of a growing period (perma:setChoice).\"@en .\n\nperma:setFor a owl:ObjectProperty ;\n    rdfs:domain perma:PlantSet ; rdfs:range skos:Concept ;\n    rdfs:label \"for surface\"@en , \"für Fläche\"@de , \"pour surface\"@fr ;\n    rdfs:comment \"The surface categories the set is made for (perma:SurfaceCategories).\"@en .\n\nperma:rationale a owl:DatatypeProperty ;\n    rdfs:domain perma:PlantSet ; rdfs:range rdfs:Literal ;\n    rdfs:label \"rationale\"@en , \"Begründung\"@de , \"raisonnement\"@fr ;\n    rdfs:comment \"Why the set's crops go together and what to watch, in a few sentences: the set's explanation page shows it (docs/adr/0028).\"@en .\n\nperma:draft a owl:DatatypeProperty ;\n    rdfs:domain perma:PlantSet ; rdfs:range xsd:boolean ;\n    rdfs:label \"draft\"@en , \"Entwurf\"@de , \"brouillon\"@fr ;\n    rdfs:comment \"Proposed (by a person or the edge's agent) and not yet reviewed into the shared library.\"@en .\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix owl:     <http://www.w3.org/2002/07/owl#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n\n# ============================================================\n# perma-core, habitat module, v0.1: the places of one habitat (a DHC home,\n# ADR 0015) and what grows there, as its owners map it.\n#\n#   - a GARDEN ZONE, shown to people as an AREA of the site: the roof, the garden, a balcony. Its exposure and a\n#     microclimate offset adjust the area's climate (a roof is warmer and\n#     windier than the street).\n#   - a GUILD (Perma5Guild): an area's working unit of bed, worm box, tank,\n#     sensors and robot(s). Its type (WormBed5 ...) fixes the structure.\n#   - a GROWING BED in a zone, split into square cells: the grid a person\n#     plants by hand today and a gantry robot can work later.\n#   - a PLANTING CELL: where one plant or sowing point stands. Only planted\n#     cells are stored; the crop's spacing gives how many cells it covers.\n#   - a GARDEN PLANT: a plant kept for years at one spot, e.g. a fruit tree.\n#     Positions are in metres inside its zone, never geographic.\n#   - a guild's WATER (v0.2, docs/adr/0025): rain catchments, water stores (a\n#     rain barrel, the bed's tank pipes, the worm box's sump, a garden tank)\n#     and the valves between them. Worm liquid and clean water are kept apart.\n#\n# The things are the habitat's own (id space of the app); crops are linked\n# from the shared library by IRI. Namespace provisional, as the other modules.\n# ============================================================\n\n<https://permaculture.digitalhome.cloud/ontology/habitat>\n    a owl:Ontology ;\n    rdfs:label \"perma-core: habitat\"@en , \"perma-core: Lebensraum\"@de , \"perma-core : habitat\"@fr ;\n    dcterms:description \"Zones, growing beds with their cells, and long-lived plants of one habitat.\"@en ;\n    owl:versionInfo \"0.2.0\" .\n\n# ------------------------------------------------------------ classes\n\nperma:GardenZone a owl:Class ;\n    rdfs:label \"Area\"@en , \"Bereich\"@de , \"Zone\"@fr ;\n    rdfs:comment \"An area of a site, with one microclimate: the roof, the garden, a balcony. People call it an area; the class keeps its first name.\"@en .\n\nperma:Guild a owl:Class ;\n    rdfs:label \"Perma5Guild\"@en , \"Perma5Guild\"@de , \"Perma5Guild\"@fr ;\n    rdfs:comment \"An area's working unit: its bed, worm box, tank, sensors and robot(s), kept and run together. A guild TYPE (perma:guildType, e.g. WormBed5) fixes the structure: the parts, the jobs, the sensors. An instance sets the sizes and settings. One edge runs one guild (docs/adr/0020, docs/specs/perma5guild.md).\"@en .\n\nperma:GrowingBed a owl:Class ;\n    rdfs:label \"Growing bed\"@en , \"Beet\"@de , \"Planche de culture\"@fr ;\n    rdfs:comment \"A rectangular bed in a zone, split into square cells (row 0 and column 0 at one corner).\"@en .\n\nperma:BedFarm a owl:Class ;\n    rdfs:label \"Farm of beds\"@en , \"Beetfeld\"@de , \"Ensemble de planches\"@fr ;\n    rdfs:comment \"Rectangle beds of one size in rows, with paths between them: the surface category perma:BedFarmSurface. Its beds are ordinary growing beds that say perma:inFarm.\"@en .\n\nperma:GrowingPeriod a owl:Class ;\n    rdfs:label \"Growing period\"@en , \"Anbauabschnitt\"@de , \"Période de culture\"@fr ;\n    rdfs:comment \"A stretch of a bed's year, by month: a growing period with its plant sets and its target (the cells that say perma:inPeriod), or a rest. A bed's periods do not overlap; the bed works through them year after year (docs/adr/0029).\"@en .\n\nperma:PlantingCell a owl:Class ;\n    rdfs:label \"Planting cell\"@en , \"Pflanzzelle\"@de , \"Case de plantation\"@fr ;\n    rdfs:comment \"Where one plant or sowing point of a bed stands, with its crop and how far it has got.\"@en .\n\nperma:GardenPlant a owl:Class ;\n    rdfs:label \"Garden plant\"@en , \"Gartenpflanze\"@de , \"Plante du jardin\"@fr ;\n    rdfs:comment \"A plant kept for years at one spot of a zone, e.g. a fruit tree or a currant bush.\"@en .\n\n# ------------------------------------------------------------ zones\n\nperma:zoneKind a owl:ObjectProperty ;\n    rdfs:domain perma:GardenZone ; rdfs:range skos:Concept ;\n    rdfs:label \"kind of area\"@en , \"Art des Bereichs\"@de , \"type de zone\"@fr ;\n    rdfs:comment \"One concept from perma:ZoneKinds.\"@en .\n\nperma:exposure a owl:ObjectProperty ;\n    rdfs:domain perma:GardenZone ; rdfs:range skos:Concept ;\n    rdfs:label \"exposure\"@en , \"Lage\"@de , \"exposition\"@fr ;\n    rdfs:comment \"Concepts from perma:Exposures: sun, half shade, shade, windy.\"@en .\n\nperma:areaM2 a owl:DatatypeProperty ;\n    rdfs:domain perma:GardenZone ; rdfs:range xsd:decimal ;\n    rdfs:label \"area (m²)\"@en , \"Fläche (m²)\"@de , \"surface (m²)\"@fr .\n\nperma:microclimateOffsetC a owl:DatatypeProperty ;\n    rdfs:domain perma:GardenZone ; rdfs:range xsd:decimal ;\n    rdfs:label \"microclimate offset (°C)\"@en , \"Mikroklima-Abweichung (°C)\"@de , \"écart microclimatique (°C)\"@fr ;\n    rdfs:comment \"Added to the area's monthly temperatures for this zone: about +1 on a roof, 0 in an open garden, below 0 in a frost hollow.\"@en .\n\nperma:inZone a owl:ObjectProperty ;\n    rdfs:range perma:GardenZone ;\n    rdfs:label \"in area\"@en , \"im Bereich\"@de , \"dans la zone\"@fr .\n\n# ------------------------------------------------------------ guilds\n\nperma:guildType a owl:ObjectProperty ;\n    rdfs:domain perma:Guild ; rdfs:range skos:Concept ;\n    rdfs:label \"guild type\"@en , \"Gildentyp\"@de , \"type de guilde\"@fr ;\n    rdfs:comment \"One concept from perma:GuildTypes. The first is perma:WormBed5: a flat bed with a worm box at one end, worked by a gantry.\"@en .\n\nperma:robotModel a owl:ObjectProperty ;\n    rdfs:domain perma:Guild ; rdfs:range skos:Concept ;\n    rdfs:label \"robot\"@en , \"Roboter\"@de , \"robot\"@fr ;\n    rdfs:comment \"The robot that works the guild: one concept from perma:RobotModels, e.g. perma:Gantry5Gen1 (Gantry5, first generation).\"@en .\n\nperma:wormsMayLeave a owl:DatatypeProperty ;\n    rdfs:domain perma:Guild ; rdfs:range xsd:boolean ;\n    rdfs:label \"worms may leave the box\"@en , \"Würmer dürfen die Kiste verlassen\"@de , \"les vers peuvent quitter le bac\"@fr ;\n    rdfs:comment \"True: the worm box has exits into the bed's soil, a refuge when the box turns too hot, cold or sour. False: a closed box, with cleaner measurements and no refuge.\"@en .\n\nperma:inGuild a owl:ObjectProperty ;\n    rdfs:range perma:Guild ;\n    rdfs:label \"in guild\"@en , \"in der Gilde\"@de , \"dans la guilde\"@fr ;\n    rdfs:comment \"The guild a bed or a water part belongs to. A bed without one is a plain bed, worked by hand. A water part may stand in another area than its guild (a garden tank), so its own perma:inZone says where.\"@en .\n\n# ------------------------------------------------------------ beds and cells\n\nperma:lengthCm a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"length (cm)\"@en , \"Länge (cm)\"@de , \"longueur (cm)\"@fr ;\n    rdfs:comment \"Along the columns.\"@en .\n\nperma:widthCm a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"width (cm)\"@en , \"Breite (cm)\"@de , \"largeur (cm)\"@fr ;\n    rdfs:comment \"Along the rows.\"@en .\n\nperma:substrateDepthCm a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"substrate depth (cm)\"@en , \"Substrattiefe (cm)\"@de , \"profondeur du substrat (cm)\"@fr ;\n    rdfs:comment \"The soil the plants root in, above the tank pipes when the bed has them.\"@en .\n\nperma:cellSizeCm a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"cell size (cm)\"@en , \"Zellgröße (cm)\"@de , \"taille de case (cm)\"@fr .\n\nperma:substrateKind a owl:ObjectProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range skos:Concept ;\n    rdfs:label \"substrate\"@en , \"Substrat\"@de , \"substrat\"@fr ;\n    rdfs:comment \"One concept from perma:SubstrateKinds. It sets how heavy the wet bed is (docs/specs/roofbed-system.md).\"@en .\n\nperma:tankPipeCount a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"tank pipes\"@en , \"Tankrohre\"@de , \"tuyaux réservoir\"@fr ;\n    rdfs:comment \"Drain pipes lying under the substrate along the bed's length: the water tank of a wicking bed. The soil draws the water up from below.\"@en .\n\nperma:tankPipeMm a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"pipe diameter (mm)\"@en , \"Rohrdurchmesser (mm)\"@de , \"diamètre des tuyaux (mm)\"@fr ;\n    rdfs:comment \"Outer diameter of the tank pipes, e.g. 110.\"@en .\n\nperma:mulchCm a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"mulch (cm)\"@en , \"Mulch (cm)\"@de , \"paillis (cm)\"@fr ;\n    rdfs:comment \"Thickness of the mulch on the bed, 0 for none. It keeps the soil moist and most weeds down. On a robot bed keep it thin (up to about 3 cm): a thick mulch stops a seeder and hides the soil from the camera.\"@en .\n\nperma:wormBinCm a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range xsd:integer ;\n    rdfs:label \"worm box (cm)\"@en , \"Wurmkiste (cm)\"@de , \"lombricomposteur (cm)\"@fr ;\n    rdfs:comment \"Length of the bed's far end (the highest columns) taken by a worm compost box: two bins, the upper one above the soil for the worms, the lower one a sump for the liquid, which a tap lets on to the tank pipes. No cells are planted there.\"@en .\n\nperma:surfaceCategory a owl:ObjectProperty ;\n    rdfs:range skos:Concept ;\n    rdfs:label \"surface category\"@en , \"Flächenart\"@de , \"catégorie de surface\"@fr ;\n    rdfs:comment \"What kind of surface a bed or farm is (perma:SurfaceCategories). Each category has its own limits and its own planner; a bed without one is a rectangle bed.\"@en .\n\nperma:inFarm a owl:ObjectProperty ;\n    rdfs:domain perma:GrowingBed ; rdfs:range perma:BedFarm ;\n    rdfs:label \"in farm\"@en , \"im Beetfeld\"@de , \"dans l'ensemble\"@fr .\n\nperma:bedRows a owl:DatatypeProperty ;\n    rdfs:domain perma:BedFarm ; rdfs:range xsd:integer ;\n    rdfs:label \"rows of beds\"@en , \"Beetreihen\"@de , \"rangs de planches\"@fr .\n\nperma:bedsPerRow a owl:DatatypeProperty ;\n    rdfs:domain perma:BedFarm ; rdfs:range xsd:integer ;\n    rdfs:label \"beds per row\"@en , \"Beete je Reihe\"@de , \"planches par rang\"@fr .\n\nperma:pathCm a owl:DatatypeProperty ;\n    rdfs:domain perma:BedFarm ; rdfs:range xsd:integer ;\n    rdfs:label \"path (cm)\"@en , \"Weg (cm)\"@de , \"allée (cm)\"@fr ;\n    rdfs:comment \"Width of the paths between the beds.\"@en .\n\nperma:bedLengthCm a owl:DatatypeProperty ;\n    rdfs:domain perma:BedFarm ; rdfs:range xsd:integer ;\n    rdfs:label \"bed length (cm)\"@en , \"Beetlänge (cm)\"@de , \"longueur des planches (cm)\"@fr .\n\nperma:bedWidthCm a owl:DatatypeProperty ;\n    rdfs:domain perma:BedFarm ; rdfs:range xsd:integer ;\n    rdfs:label \"bed width (cm)\"@en , \"Beetbreite (cm)\"@de , \"largeur des planches (cm)\"@fr .\n\nperma:ofBed a owl:ObjectProperty ;\n    rdfs:domain perma:GrowingPeriod ; rdfs:range perma:GrowingBed ;\n    rdfs:label \"of bed\"@en , \"des Beets\"@de , \"de la planche\"@fr .\n\nperma:fromMonth a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingPeriod ; rdfs:range xsd:integer ;\n    rdfs:label \"from month\"@en , \"ab Monat\"@de , \"du mois\"@fr ;\n    rdfs:comment \"The period's first month, 1..12.\"@en .\n\nperma:toMonth a owl:DatatypeProperty ;\n    rdfs:domain perma:GrowingPeriod ; rdfs:range xsd:integer ;\n    rdfs:label \"to month\"@en , \"bis Monat\"@de , \"au mois\"@fr ;\n    rdfs:comment \"The period's last month, 1..12; below perma:fromMonth it lies in the next year (November to February).\"@en .\n\nperma:periodKind a owl:ObjectProperty ;\n    rdfs:domain perma:GrowingPeriod ; rdfs:range skos:Concept ;\n    rdfs:label \"kind\"@en , \"Art\"@de , \"type\"@fr ;\n    rdfs:comment \"One concept from perma:PeriodKinds: growing or rest.\"@en .\n\nperma:setChoice a owl:ObjectProperty ;\n    rdfs:domain perma:GrowingPeriod ;\n    rdfs:label \"plant set chosen\"@en , \"gewähltes Pflanzenset\"@de , \"ensemble choisi\"@fr ;\n    rdfs:comment \"A plant set the period is planted from, with its share of the room (perma:plantSet, perma:share). A rest period's set is its cover crop.\"@en .\n\nperma:plantSet a owl:ObjectProperty ;\n    rdfs:range perma:PlantSet ;\n    rdfs:label \"plant set\"@en , \"Pflanzenset\"@de , \"ensemble de plantes\"@fr .\n\nperma:inPeriod a owl:ObjectProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range perma:GrowingPeriod ;\n    rdfs:label \"in period\"@en , \"im Abschnitt\"@de , \"dans la période\"@fr ;\n    rdfs:comment \"The growing period whose target this cell is. A cell without one belongs to the bed as it stands.\"@en .\n\nperma:inBed a owl:ObjectProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range perma:GrowingBed ;\n    rdfs:label \"in bed\"@en , \"im Beet\"@de , \"dans la planche\"@fr .\n\nperma:row a owl:DatatypeProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range xsd:integer ;\n    rdfs:label \"row\"@en , \"Reihe\"@de , \"rangée\"@fr .\n\nperma:col a owl:DatatypeProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range xsd:integer ;\n    rdfs:label \"column\"@en , \"Spalte\"@de , \"colonne\"@fr .\n\nperma:grows a owl:ObjectProperty ;\n    rdfs:range perma:Crop ;\n    rdfs:label \"grows\"@en , \"trägt\"@de , \"porte\"@fr ;\n    rdfs:comment \"The crop of the library a cell or a garden plant grows.\"@en .\n\nperma:cellStatus a owl:ObjectProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range skos:Concept ;\n    rdfs:label \"status\"@en , \"Stand\"@de , \"état\"@fr ;\n    rdfs:comment \"One concept from perma:CellStatuses: planned, sown, growing, harvested, lost.\"@en .\n\nperma:cellSowingDepthMm a owl:DatatypeProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range xsd:integer ;\n    rdfs:label \"sowing depth here (mm)\"@en , \"Saattiefe hier (mm)\"@de , \"profondeur de semis ici (mm)\"@fr ;\n    rdfs:comment \"Only when this cell differs from the crop's perma:sowingDepthMm.\"@en .\n\nperma:cellSeedsPerPoint a owl:DatatypeProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range xsd:integer ;\n    rdfs:label \"seeds here\"@en , \"Samen hier\"@de , \"graines ici\"@fr ;\n    rdfs:comment \"Only when this cell differs from the crop's perma:seedsPerPoint.\"@en .\n\nperma:sownOn a owl:DatatypeProperty ;\n    rdfs:domain perma:PlantingCell ; rdfs:range xsd:date ;\n    rdfs:label \"sown on\"@en , \"gesät am\"@de , \"semé le\"@fr .\n\n# ------------------------------------------------------------ garden plants\n\nperma:plantedYear a owl:DatatypeProperty ;\n    rdfs:domain perma:GardenPlant ; rdfs:range xsd:integer ;\n    rdfs:label \"planted in\"@en , \"gepflanzt\"@de , \"planté en\"@fr .\n\nperma:rootstock a owl:DatatypeProperty ;\n    rdfs:domain perma:GardenPlant ; rdfs:range xsd:string ;\n    rdfs:label \"rootstock\"@en , \"Unterlage\"@de , \"porte-greffe\"@fr ;\n    rdfs:comment \"For a grafted tree: the rootstock, which sets its size (e.g. Quince A, St Julien A, Gisela 5).\"@en .\n\nperma:xM a owl:DatatypeProperty ;\n    rdfs:domain perma:GardenPlant ; rdfs:range xsd:decimal ;\n    rdfs:label \"x (m)\"@en , \"x (m)\"@de , \"x (m)\"@fr ;\n    rdfs:comment \"Metres from the zone's left edge, on the zone's own sketch.\"@en .\n\nperma:yM a owl:DatatypeProperty ;\n    rdfs:domain perma:GardenPlant ; rdfs:range xsd:decimal ;\n    rdfs:label \"y (m)\"@en , \"y (m)\"@de , \"y (m)\"@fr ;\n    rdfs:comment \"Metres from the zone's top edge, on the zone's own sketch.\"@en .\n\n# ------------------------------------------------------------ water (v0.2, docs/adr/0025)\n#\n#   roof catchment ─gutter→ rain barrel ─tap→ tank pipes (the bed)\n#   worm box sump ─valve→ tank pipes\n#   worm box sump ─valve→ garden tank          the surplus, for the trees\n#\n# A store HOLDS clean water, worm liquid or both. Worm liquid never flows into\n# a store kept for clean water (a barrel that feeds the gantry's nozzle): the\n# shapes refuse it. That is roofbed-system.md's \"never on leaves\" as data.\n\nperma:RainCatchment a owl:Class ;\n    rdfs:label \"Rain catchment\"@en , \"Regenfläche\"@de , \"Surface de captage\"@fr ;\n    rdfs:comment \"A surface whose rain is collected, e.g. a stretch of roof with its gutter.\"@en .\n\nperma:WaterStore a owl:Class ;\n    rdfs:label \"Water store\"@en , \"Wasserspeicher\"@de , \"Réserve d'eau\"@fr ;\n    rdfs:comment \"Something that holds water or worm liquid: a rain barrel, a bed's tank pipes, a worm box's sump, a garden tank. Its kind is a concept from perma:WaterStoreKinds.\"@en .\n\nperma:Valve a owl:Class ;\n    rdfs:label \"Valve\"@en , \"Ventil\"@de , \"Vanne\"@fr ;\n    rdfs:comment \"A tap between two parts: water or liquid flows from one to the other while it is open. A person opens a manual tap; an edge valve opens when the edge does it, after a person confirmed.\"@en .\n\nperma:catchmentM2 a owl:DatatypeProperty ;\n    rdfs:domain perma:RainCatchment ; rdfs:range xsd:decimal ;\n    rdfs:label \"catchment (m²)\"@en , \"Auffangfläche (m²)\"@de , \"surface de captage (m²)\"@fr ;\n    rdfs:comment \"Area that sends its rain to the store, seen from above.\"@en .\n\nperma:runoffShare a owl:DatatypeProperty ;\n    rdfs:domain perma:RainCatchment ; rdfs:range xsd:decimal ;\n    rdfs:label \"runoff share\"@en , \"Abflussanteil\"@de , \"coefficient de ruissellement\"@fr ;\n    rdfs:comment \"The share of the rain that reaches the store, 0..1: about 0.8 for a hard roof, 0.5 for a gravel roof, 0.3 for a green roof.\"@en .\n\nperma:drainsTo a owl:ObjectProperty ;\n    rdfs:domain perma:RainCatchment ; rdfs:range perma:WaterStore ;\n    rdfs:label \"drains to\"@en , \"leitet in\"@de , \"s'écoule vers\"@fr ;\n    rdfs:comment \"The store its gutter fills, without a valve.\"@en .\n\nperma:storeKind a owl:ObjectProperty ;\n    rdfs:domain perma:WaterStore ; rdfs:range skos:Concept ;\n    rdfs:label \"kind of store\"@en , \"Art des Speichers\"@de , \"type de réserve\"@fr ;\n    rdfs:comment \"One concept from perma:WaterStoreKinds.\"@en .\n\nperma:capacityL a owl:DatatypeProperty ;\n    rdfs:domain perma:WaterStore ; rdfs:range xsd:decimal ;\n    rdfs:label \"capacity (l)\"@en , \"Fassungsvermögen (l)\"@de , \"capacité (l)\"@fr .\n\nperma:holds a owl:ObjectProperty ;\n    rdfs:domain perma:WaterStore ; rdfs:range skos:Concept ;\n    rdfs:label \"holds\"@en , \"enthält\"@de , \"contient\"@fr ;\n    rdfs:comment \"What may be in it: concepts from perma:WaterKinds. A store with only perma:CleanWater never takes worm liquid.\"@en .\n\nperma:overflowTo a owl:ObjectProperty ;\n    rdfs:domain perma:WaterStore ; rdfs:range perma:WaterStore ;\n    rdfs:label \"overflows to\"@en , \"läuft über in\"@de , \"déborde vers\"@fr ;\n    rdfs:comment \"Where it goes when full. None: the roof drain or the ground.\"@en .\n\nperma:flowFrom a owl:ObjectProperty ;\n    rdfs:domain perma:Valve ; rdfs:range perma:WaterStore ;\n    rdfs:label \"from\"@en , \"von\"@de , \"de\"@fr .\n\nperma:flowTo a owl:ObjectProperty ;\n    rdfs:domain perma:Valve ; rdfs:range perma:WaterStore ;\n    rdfs:label \"to\"@en , \"nach\"@de , \"vers\"@fr .\n\nperma:valveKind a owl:ObjectProperty ;\n    rdfs:domain perma:Valve ; rdfs:range skos:Concept ;\n    rdfs:label \"kind of valve\"@en , \"Art des Ventils\"@de , \"type de vanne\"@fr ;\n    rdfs:comment \"One concept from perma:ValveKinds: a manual tap or an edge valve.\"@en .\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix owl:     <http://www.w3.org/2002/07/owl#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix sosa:    <http://www.w3.org/ns/sosa/> .\n\n# ============================================================\n# perma-core, learning module, v0.1: the habitat's second brain\n# (docs/adr/0026). What its owners expect, how they measure it, what the\n# measurements said, and what they changed: plan, do, check, act.\n#\n#   - a LEARNING CYCLE is one turn of plan-do-check-act about a guild or one\n#     of its parts, e.g. \"WormBed5 sizing, first season\".\n#   - a HYPOTHESIS is a number expected, with the range inside which it\n#     holds, its unit and where it comes from: \"the worms turn over 90 kg of\n#     scraps a year (60-130)\".\n#   - a MEASURE says how it is measured and how often, and which reading of\n#     an edge fills it (perma:reading), when one can.\n#   - a CHECK is one measured value of a hypothesis on a day: an observation\n#     (sosa:Observation) by a person or an edge.\n#\n# A starter set (guides/wormbed5-sizing.json) is adopted into a guild as a\n# cycle in its Plan phase; the app and the edges then add checks. The graph\n# is the habitat's own (ADR-0007), so the guild's edge sees it too.\n# ============================================================\n\n<https://permaculture.digitalhome.cloud/ontology/learning>\n    a owl:Ontology ;\n    rdfs:label \"perma-core: learning\"@en , \"perma-core: Lernen\"@de , \"perma-core : apprentissage\"@fr ;\n    dcterms:description \"Learning cycles (plan-do-check-act) with hypotheses, measures and checks about a habitat's guilds.\"@en ;\n    owl:versionInfo \"0.1.0\" .\n\n# ------------------------------------------------------------ classes\n\nperma:LearningCycle a owl:Class ;\n    rdfs:label \"Learning cycle\"@en , \"Lernzyklus\"@de , \"Cycle d'apprentissage\"@fr ;\n    rdfs:comment \"One turn of plan, do, check and act about a guild or one of its parts.\"@en .\n\nperma:Hypothesis a owl:Class ;\n    rdfs:label \"Hypothesis\"@en , \"Hypothese\"@de , \"Hypothèse\"@fr ;\n    rdfs:comment \"A number expected, with the range inside which it holds: a baseline to be proved wrong.\"@en .\n\nperma:Measure a owl:Class ;\n    rdfs:label \"Measure\"@en , \"Messung\"@de , \"Mesure\"@fr ;\n    rdfs:comment \"How a hypothesis is measured, and how often.\"@en .\n\nperma:Check a owl:Class ;\n    rdfs:subClassOf sosa:Observation ;\n    rdfs:label \"Check\"@en , \"Prüfung\"@de , \"Vérification\"@fr ;\n    rdfs:comment \"One measured value of a hypothesis on a day, by a person or an edge (sosa:hasSimpleResult, sosa:resultTime).\"@en .\n\n# ------------------------------------------------------------ the cycle\n\nperma:about a owl:ObjectProperty ;\n    rdfs:domain perma:LearningCycle ;\n    rdfs:label \"about\"@en , \"über\"@de , \"à propos de\"@fr ;\n    rdfs:comment \"The guild, or a part of it, the cycle learns about.\"@en .\n\nperma:cyclePhase a owl:ObjectProperty ;\n    rdfs:domain perma:LearningCycle ; rdfs:range skos:Concept ;\n    rdfs:label \"phase\"@en , \"Phase\"@de , \"phase\"@fr ;\n    rdfs:comment \"Where the cycle stands: one concept from perma:CyclePhases.\"@en .\n\nperma:startedOn a owl:DatatypeProperty ;\n    rdfs:domain perma:LearningCycle ; rdfs:range xsd:date ;\n    rdfs:label \"started on\"@en , \"begonnen am\"@de , \"commencé le\"@fr .\n\nperma:endsOn a owl:DatatypeProperty ;\n    rdfs:domain perma:LearningCycle ; rdfs:range xsd:date ;\n    rdfs:label \"ends on\"@en , \"endet am\"@de , \"se termine le\"@fr ;\n    rdfs:comment \"When the season of measuring is over and the cycle is checked as a whole.\"@en .\n\nperma:fromStarter a owl:DatatypeProperty ;\n    rdfs:domain perma:LearningCycle ; rdfs:range xsd:string ;\n    rdfs:label \"starter set\"@en , \"Startsatz\"@de , \"jeu de départ\"@fr ;\n    rdfs:comment \"The starter set it was adopted from, e.g. wormbed5-sizing.\"@en .\n\nperma:hasHypothesis a owl:ObjectProperty ;\n    rdfs:domain perma:LearningCycle ; rdfs:range perma:Hypothesis ;\n    rdfs:label \"hypothesis\"@en , \"Hypothese\"@de , \"hypothèse\"@fr .\n\n# ------------------------------------------------------------ hypotheses and measures\n\nperma:code a owl:DatatypeProperty ;\n    rdfs:range xsd:string ;\n    rdfs:label \"code\"@en , \"Kürzel\"@de , \"code\"@fr ;\n    rdfs:comment \"A short name inside its cycle: H1, M3.\"@en .\n\nperma:expected a owl:DatatypeProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range xsd:decimal ;\n    rdfs:label \"expected\"@en , \"erwartet\"@de , \"attendu\"@fr .\n\nperma:low a owl:DatatypeProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range xsd:decimal ;\n    rdfs:label \"lowest that holds\"@en , \"kleinster passender Wert\"@de , \"plus bas admis\"@fr .\n\nperma:high a owl:DatatypeProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range xsd:decimal ;\n    rdfs:label \"highest that holds\"@en , \"größter passender Wert\"@de , \"plus haut admis\"@fr .\n\nperma:unit a owl:DatatypeProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range xsd:string ;\n    rdfs:label \"unit\"@en , \"Einheit\"@de , \"unité\"@fr ;\n    rdfs:comment \"As people write it: kg/yr, l/kg, g N/yr.\"@en .\n\nperma:source a owl:DatatypeProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range xsd:string ;\n    rdfs:label \"source\"@en , \"Quelle\"@de , \"source\"@fr ;\n    rdfs:comment \"Where the number comes from: a model run, a study (a URL), practice.\"@en .\n\nperma:measuredBy a owl:ObjectProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range perma:Measure ;\n    rdfs:label \"measured by\"@en , \"gemessen durch\"@de , \"mesurée par\"@fr .\n\nperma:verdict a owl:ObjectProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range skos:Concept ;\n    rdfs:label \"verdict\"@en , \"Urteil\"@de , \"verdict\"@fr ;\n    rdfs:comment \"One concept from perma:Verdicts: open, holds, fails.\"@en .\n\nperma:actTaken a owl:DatatypeProperty ;\n    rdfs:domain perma:Hypothesis ; rdfs:range xsd:string ;\n    rdfs:label \"what we changed\"@en , \"was wir geändert haben\"@de , \"ce que nous avons changé\"@fr ;\n    rdfs:comment \"The act after the check: a new number, a change to the guild, to a guide, to the twin's model.\"@en .\n\nperma:method a owl:DatatypeProperty ;\n    rdfs:domain perma:Measure ; rdfs:range rdfs:Literal ;\n    rdfs:label \"how\"@en , \"wie\"@de , \"comment\"@fr .\n\nperma:everyDays a owl:DatatypeProperty ;\n    rdfs:domain perma:Measure ; rdfs:range xsd:integer ;\n    rdfs:label \"every (days)\"@en , \"alle (Tage)\"@de , \"tous les (jours)\"@fr .\n\nperma:reading a owl:DatatypeProperty ;\n    rdfs:domain perma:Measure ; rdfs:range xsd:string ;\n    rdfs:label \"edge reading\"@en , \"Messwert der Edge\"@de , \"mesure de l'edge\"@fr ;\n    rdfs:comment \"The key of an edge's reading that fills it, e.g. wormBin.sumpL; none when a person measures.\"@en .\n\n# ------------------------------------------------------------ checks\n\nperma:ofHypothesis a owl:ObjectProperty ;\n    rdfs:domain perma:Check ; rdfs:range perma:Hypothesis ;\n    rdfs:label \"of hypothesis\"@en , \"zur Hypothese\"@de , \"de l'hypothèse\"@fr .\n\nperma:checkedBy a owl:DatatypeProperty ;\n    rdfs:domain perma:Check ; rdfs:range xsd:string ;\n    rdfs:label \"checked by\"@en , \"geprüft von\"@de , \"vérifié par\"@fr ;\n    rdfs:comment \"person or edge.\"@en .\n";
export const CONCEPTS = "@prefix app:     <https://permtek-5.digitalhome.cloud/ontology#> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n\n# ============================================================\n# Concept schemes (SKOS), v0.1: a PLACEHOLDER.\n#\n# New types are added HERE, as data: no code or schema change. Each concept\n# needs an English prefLabel (the master); German and French are expected.\n# ============================================================\n\napp:ThingTypes a skos:ConceptScheme ;\n    skos:prefLabel \"Types of things\"@en , \"Arten von Dingen\"@de , \"Types de choses\"@fr ;\n    skos:hasTopConcept app:Device , app:Document .\n\napp:Device a skos:Concept ; skos:inScheme app:ThingTypes ; skos:topConceptOf app:ThingTypes ;\n    skos:prefLabel \"Device\"@en , \"Gerät\"@de , \"Appareil\"@fr .\n\napp:Document a skos:Concept ; skos:inScheme app:ThingTypes ; skos:topConceptOf app:ThingTypes ;\n    skos:prefLabel \"Document\"@en , \"Dokument\"@de , \"Document\"@fr .\n\n@prefix perma: <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix skos:  <http://www.w3.org/2004/02/skos/core#> .\n\n# ============================================================\n# perma-core, vegetation concept schemes, v0.1\n#\n# New classes of vegetation are added HERE, as data. Each concept needs an\n# English prefLabel (the master); German and French are expected.\n# ============================================================\n\n# ------------------------------------------------------------ vegetation classes\n\nperma:VegetationClasses a skos:ConceptScheme ;\n    skos:prefLabel \"Vegetation classes\"@en , \"Vegetationsklassen\"@de , \"Classes de végétation\"@fr ;\n    skos:hasTopConcept perma:WoodyVegetation , perma:HerbaceousVegetation , perma:BareSoil .\n\nperma:WoodyVegetation a skos:Concept ; skos:inScheme perma:VegetationClasses ;\n    skos:topConceptOf perma:VegetationClasses ;\n    skos:prefLabel \"Woody vegetation\"@en , \"Gehölze\"@de , \"Végétation ligneuse\"@fr .\n\nperma:Tree a skos:Concept ; skos:inScheme perma:VegetationClasses ; skos:broader perma:WoodyVegetation ;\n    skos:prefLabel \"Tree\"@en , \"Baum\"@de , \"Arbre\"@fr ;\n    skos:definition \"A woody plant with a trunk, usually above 5 m, with a canopy.\"@en .\n\nperma:Shrub a skos:Concept ; skos:inScheme perma:VegetationClasses ; skos:broader perma:WoodyVegetation ;\n    skos:prefLabel \"Shrub\"@en , \"Strauch\"@de , \"Arbuste\"@fr ;\n    skos:definition \"A woody plant with several stems, usually below 5 m.\"@en .\n\nperma:Hedge a skos:Concept ; skos:inScheme perma:VegetationClasses ; skos:broader perma:WoodyVegetation ;\n    skos:prefLabel \"Hedge\"@en , \"Hecke\"@de , \"Haie\"@fr ;\n    skos:definition \"A line of shrubs and small trees, planted or grown along a boundary.\"@en .\n\nperma:Bramble a skos:Concept ; skos:inScheme perma:VegetationClasses ; skos:broader perma:WoodyVegetation ;\n    skos:prefLabel \"Bramble thicket\"@en , \"Brombeergestrüpp\"@de , \"Roncier\"@fr ;\n    skos:definition \"A dense thicket of brambles (Rubus) or similar thorny scrub; impassable for people and small machines.\"@en .\n\nperma:HerbaceousVegetation a skos:Concept ; skos:inScheme perma:VegetationClasses ;\n    skos:topConceptOf perma:VegetationClasses ;\n    skos:prefLabel \"Herbaceous vegetation\"@en , \"Krautige Vegetation\"@de , \"Végétation herbacée\"@fr .\n\nperma:Meadow a skos:Concept ; skos:inScheme perma:VegetationClasses ; skos:broader perma:HerbaceousVegetation ;\n    skos:prefLabel \"Meadow\"@en , \"Wiese\"@de , \"Prairie\"@fr ;\n    skos:definition \"Grassland kept short by mowing or grazing.\"@en .\n\nperma:TallGrass a skos:Concept ; skos:inScheme perma:VegetationClasses ; skos:broader perma:HerbaceousVegetation ;\n    skos:prefLabel \"Tall grass\"@en , \"Hochgras\"@de , \"Herbes hautes\"@fr ;\n    skos:definition \"Unmown grassland and tall herbs, roughly knee-high or more.\"@en .\n\nperma:Crop a skos:Concept ; skos:inScheme perma:VegetationClasses ; skos:broader perma:HerbaceousVegetation ;\n    skos:prefLabel \"Crop bed\"@en , \"Beet\"@de , \"Planche de culture\"@fr ;\n    skos:definition \"Vegetables, herbs or green manure grown in beds.\"@en .\n\nperma:BareSoil a skos:Concept ; skos:inScheme perma:VegetationClasses ;\n    skos:topConceptOf perma:VegetationClasses ;\n    skos:prefLabel \"Bare soil\"@en , \"Offener Boden\"@de , \"Sol nu\"@fr ;\n    skos:definition \"Soil without plant cover: paths, freshly worked ground, erosion scars.\"@en .\n\n# ------------------------------------------------------------ vegetation statuses\n\nperma:VegetationStatuses a skos:ConceptScheme ;\n    skos:prefLabel \"Vegetation statuses\"@en , \"Vegetationsstatus\"@de , \"Statuts de la végétation\"@fr ;\n    skos:hasTopConcept perma:Existing , perma:Planted , perma:Planned .\n\nperma:Existing a skos:Concept ; skos:inScheme perma:VegetationStatuses ; skos:topConceptOf perma:VegetationStatuses ;\n    skos:prefLabel \"Existing\"@en , \"Bestand\"@de , \"Existant\"@fr ;\n    skos:definition \"Was there before the design: wild, self-sown or inherited.\"@en .\n\nperma:Planted a skos:Concept ; skos:inScheme perma:VegetationStatuses ; skos:topConceptOf perma:VegetationStatuses ;\n    skos:prefLabel \"Planted\"@en , \"Gepflanzt\"@de , \"Planté\"@fr ;\n    skos:definition \"Planted or sown as part of the design.\"@en .\n\nperma:Planned a skos:Concept ; skos:inScheme perma:VegetationStatuses ; skos:topConceptOf perma:VegetationStatuses ;\n    skos:prefLabel \"Planned\"@en , \"Geplant\"@de , \"Prévu\"@fr ;\n    skos:definition \"In the design, not in the ground yet.\"@en .\n\n# ------------------------------------------------------------ map statuses\n\nperma:MapStatuses a skos:ConceptScheme ;\n    skos:prefLabel \"Map statuses\"@en , \"Kartenstatus\"@de , \"Statuts cartographiques\"@fr ;\n    skos:hasTopConcept perma:ToConfirm , perma:Confirmed , perma:Rejected ;\n    skos:note \"Mirrors perma-core's Suggested / Confirmed / Rejected for map entries; to be merged with that scheme when perma-core joins this folder.\"@en .\n\nperma:ToConfirm a skos:Concept ; skos:inScheme perma:MapStatuses ; skos:topConceptOf perma:MapStatuses ;\n    skos:prefLabel \"To confirm\"@en , \"Zu bestätigen\"@de , \"À confirmer\"@fr ;\n    skos:definition \"Traced from a plan or an aerial photo, or suggested by a rover; nobody has checked it on site yet.\"@en .\n\nperma:Confirmed a skos:Concept ; skos:inScheme perma:MapStatuses ; skos:topConceptOf perma:MapStatuses ;\n    skos:prefLabel \"Confirmed\"@en , \"Bestätigt\"@de , \"Confirmé\"@fr .\n\nperma:Rejected a skos:Concept ; skos:inScheme perma:MapStatuses ; skos:topConceptOf perma:MapStatuses ;\n    skos:prefLabel \"Rejected\"@en , \"Verworfen\"@de , \"Rejeté\"@fr .\n\n@prefix perma: <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix skos:  <http://www.w3.org/2004/02/skos/core#> .\n\n# ============================================================\n# perma-core, food concept schemes, v0.1. New parts and activities are data.\n# ============================================================\n\nperma:PlantParts a skos:ConceptScheme ;\n    skos:prefLabel \"Plant parts\"@en , \"Pflanzenteile\"@de , \"Parties de plante\"@fr ;\n    skos:hasTopConcept perma:Fruit , perma:Bulb , perma:Leaf , perma:Seed , perma:Root , perma:Tuber , perma:Flower .\n\nperma:Fruit a skos:Concept ; skos:inScheme perma:PlantParts ; skos:topConceptOf perma:PlantParts ;\n    skos:prefLabel \"Fruit\"@en , \"Frucht\"@de , \"Fruit\"@fr .\nperma:Bulb a skos:Concept ; skos:inScheme perma:PlantParts ; skos:topConceptOf perma:PlantParts ;\n    skos:prefLabel \"Bulb\"@en , \"Zwiebel\"@de , \"Bulbe\"@fr .\nperma:Leaf a skos:Concept ; skos:inScheme perma:PlantParts ; skos:topConceptOf perma:PlantParts ;\n    skos:prefLabel \"Leaf\"@en , \"Blatt\"@de , \"Feuille\"@fr .\nperma:Seed a skos:Concept ; skos:inScheme perma:PlantParts ; skos:topConceptOf perma:PlantParts ;\n    skos:prefLabel \"Seed\"@en , \"Samen\"@de , \"Graine\"@fr .\nperma:Root a skos:Concept ; skos:inScheme perma:PlantParts ; skos:topConceptOf perma:PlantParts ;\n    skos:prefLabel \"Root\"@en , \"Wurzel\"@de , \"Racine\"@fr .\nperma:Tuber a skos:Concept ; skos:inScheme perma:PlantParts ; skos:topConceptOf perma:PlantParts ;\n    skos:prefLabel \"Tuber\"@en , \"Knolle\"@de , \"Tubercule\"@fr .\nperma:Flower a skos:Concept ; skos:inScheme perma:PlantParts ; skos:topConceptOf perma:PlantParts ;\n    skos:prefLabel \"Flower\"@en , \"Blüte\"@de , \"Fleur\"@fr .\n\nperma:GardenActivities a skos:ConceptScheme ;\n    skos:prefLabel \"Garden activities\"@en , \"Gartenarbeiten\"@de , \"Travaux du jardin\"@fr ;\n    skos:hasTopConcept perma:SowIndoors , perma:SowOutdoors , perma:PlantOut , perma:Harvest , perma:SaveSeed ,\n                       perma:Flowering , perma:WinterPrune , perma:SummerPrune .\n\nperma:SowIndoors a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Sow under cover\"@en , \"Vorziehen\"@de , \"Semis sous abri\"@fr .\nperma:SowOutdoors a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Sow outdoors\"@en , \"Direktsaat\"@de , \"Semis en pleine terre\"@fr .\nperma:PlantOut a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Plant out\"@en , \"Auspflanzen\"@de , \"Plantation\"@fr .\nperma:Harvest a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Harvest\"@en , \"Ernte\"@de , \"Récolte\"@fr .\n\nperma:PreservationMethods a skos:ConceptScheme ;\n    skos:prefLabel \"Preservation methods\"@en , \"Konservierungsarten\"@de , \"Modes de conservation\"@fr ;\n    skos:hasTopConcept perma:Fresh , perma:Cellar , perma:Dried , perma:Frozen , perma:Pickled ,\n                       perma:Fermented , perma:Bottled , perma:Macerated .\n\nperma:Fresh a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Fresh\"@en , \"Frisch\"@de , \"Frais\"@fr ;\n    skos:definition \"Used in the days or weeks after the harvest.\"@en .\nperma:Cellar a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Cellar storage\"@en , \"Einlagern\"@de , \"Conservation en cave\"@fr ;\n    skos:definition \"Kept whole, cool, dark and dry or humid as the crop needs (onions, roots, squash, apples).\"@en .\nperma:Dried a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Dried\"@en , \"Getrocknet\"@de , \"Séché\"@fr ;\n    skos:definition \"Air- or sun-dried, or in a dryer (herbs, seeds, peppers, beans).\"@en .\nperma:Frozen a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Frozen\"@en , \"Eingefroren\"@de , \"Congelé\"@fr .\nperma:Pickled a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Pickled in vinegar\"@en , \"In Essig eingelegt\"@de , \"Au vinaigre\"@fr .\nperma:Fermented a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Lacto-fermented\"@en , \"Milchsauer vergoren\"@de , \"Lacto-fermenté\"@fr .\nperma:Bottled a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Bottled (sterilised)\"@en , \"Eingekocht\"@de , \"Stérilisé en bocaux\"@fr .\n\nperma:SaveSeed a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Save seed\"@en , \"Saatgut ernten\"@de , \"Récolte des semences\"@fr .\n\nperma:LifeCycles a skos:ConceptScheme ;\n    skos:prefLabel \"Life cycles\"@en , \"Lebenszyklen\"@de , \"Cycles de vie\"@fr ;\n    skos:hasTopConcept perma:Annual , perma:Biennial , perma:Perennial .\nperma:Annual a skos:Concept ; skos:inScheme perma:LifeCycles ; skos:topConceptOf perma:LifeCycles ;\n    skos:prefLabel \"Annual\"@en , \"Einjährig\"@de , \"Annuelle\"@fr .\nperma:Biennial a skos:Concept ; skos:inScheme perma:LifeCycles ; skos:topConceptOf perma:LifeCycles ;\n    skos:prefLabel \"Biennial\"@en , \"Zweijährig\"@de , \"Bisannuelle\"@fr ;\n    skos:definition \"Sets seed in its second year: keep the best plants (or bulbs, roots) over winter and replant them.\"@en .\nperma:Perennial a skos:Concept ; skos:inScheme perma:LifeCycles ; skos:topConceptOf perma:LifeCycles ;\n    skos:prefLabel \"Perennial\"@en , \"Mehrjährig\"@de , \"Vivace\"@fr .\n\nperma:PollinationTypes a skos:ConceptScheme ;\n    skos:prefLabel \"Pollination\"@en , \"Bestäubung\"@de , \"Pollinisation\"@fr ;\n    skos:hasTopConcept perma:SelfPollinating , perma:InsectPollinated , perma:WindPollinated .\nperma:SelfPollinating a skos:Concept ; skos:inScheme perma:PollinationTypes ; skos:topConceptOf perma:PollinationTypes ;\n    skos:prefLabel \"Mostly self-pollinating\"@en , \"Überwiegend selbstbestäubend\"@de , \"Surtout autogame\"@fr .\nperma:InsectPollinated a skos:Concept ; skos:inScheme perma:PollinationTypes ; skos:topConceptOf perma:PollinationTypes ;\n    skos:prefLabel \"Insect-pollinated\"@en , \"Insektenbestäubt\"@de , \"Pollinisation par les insectes\"@fr .\nperma:WindPollinated a skos:Concept ; skos:inScheme perma:PollinationTypes ; skos:topConceptOf perma:PollinationTypes ;\n    skos:prefLabel \"Wind-pollinated\"@en , \"Windbestäubt\"@de , \"Pollinisation par le vent\"@fr .\nperma:Macerated a skos:Concept ; skos:inScheme perma:PreservationMethods ; skos:topConceptOf perma:PreservationMethods ;\n    skos:prefLabel \"Macerated in alcohol\"@en , \"In Alkohol angesetzt\"@de , \"Macéré dans l'alcool\"@fr .\n\nperma:PropagationMethods a skos:ConceptScheme ;\n    skos:prefLabel \"Propagation methods\"@en , \"Vermehrungsarten\"@de , \"Modes de multiplication\"@fr ;\n    skos:hasTopConcept perma:FromSeed , perma:FromCloves , perma:FromCuttings , perma:ByDivision , perma:ByGrafting .\nperma:FromSeed a skos:Concept ; skos:inScheme perma:PropagationMethods ; skos:topConceptOf perma:PropagationMethods ;\n    skos:prefLabel \"From seed\"@en , \"Aus Samen\"@de , \"Par semis\"@fr .\nperma:FromCloves a skos:Concept ; skos:inScheme perma:PropagationMethods ; skos:topConceptOf perma:PropagationMethods ;\n    skos:prefLabel \"From cloves or bulbils\"@en , \"Aus Zehen oder Brutzwiebeln\"@de , \"Par caïeux\"@fr .\nperma:FromCuttings a skos:Concept ; skos:inScheme perma:PropagationMethods ; skos:topConceptOf perma:PropagationMethods ;\n    skos:prefLabel \"From cuttings\"@en , \"Aus Stecklingen\"@de , \"Par bouturage\"@fr .\nperma:ByDivision a skos:Concept ; skos:inScheme perma:PropagationMethods ; skos:topConceptOf perma:PropagationMethods ;\n    skos:prefLabel \"By division\"@en , \"Durch Teilung\"@de , \"Par division\"@fr .\nperma:ByGrafting a skos:Concept ; skos:inScheme perma:PropagationMethods ; skos:topConceptOf perma:PropagationMethods ;\n    skos:prefLabel \"By grafting\"@en , \"Durch Veredelung\"@de , \"Par greffage\"@fr .\n\nperma:Flowering a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Flowering\"@en , \"Blüte\"@de , \"Floraison\"@fr ;\n    skos:definition \"Not work but a time to watch: a late frost now costs the year's fruit.\"@en .\nperma:WinterPrune a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Winter pruning\"@en , \"Winterschnitt\"@de , \"Taille d'hiver\"@fr .\nperma:SummerPrune a skos:Concept ; skos:inScheme perma:GardenActivities ; skos:topConceptOf perma:GardenActivities ;\n    skos:prefLabel \"Summer pruning\"@en , \"Sommerschnitt\"@de , \"Taille d'été\"@fr ;\n    skos:definition \"Stone fruit (plum, cherry) is pruned in summer only: winter cuts let in silver leaf and canker.\"@en .\n\n# ------------------------------------------------------------ mixed planting: what a crop takes and gives\n\nperma:FeedingLevels a skos:ConceptScheme ;\n    skos:prefLabel \"Feeding levels\"@en , \"Nährstoffbedarf\"@de , \"Besoins en nutriments\"@fr ;\n    skos:hasTopConcept perma:HeavyFeeder , perma:MediumFeeder , perma:LightFeeder , perma:SoilBuilder .\nperma:HeavyFeeder a skos:Concept ; skos:inScheme perma:FeedingLevels ; skos:topConceptOf perma:FeedingLevels ;\n    skos:prefLabel \"Heavy feeder\"@en , \"Starkzehrer\"@de , \"Gourmand\"@fr ;\n    skos:definition \"Takes much from the soil (tomato, cabbage, courgette): gets the compost.\"@en .\nperma:MediumFeeder a skos:Concept ; skos:inScheme perma:FeedingLevels ; skos:topConceptOf perma:FeedingLevels ;\n    skos:prefLabel \"Medium feeder\"@en , \"Mittelzehrer\"@de , \"Moyennement exigeant\"@fr .\nperma:LightFeeder a skos:Concept ; skos:inScheme perma:FeedingLevels ; skos:topConceptOf perma:FeedingLevels ;\n    skos:prefLabel \"Light feeder\"@en , \"Schwachzehrer\"@de , \"Peu exigeant\"@fr .\nperma:SoilBuilder a skos:Concept ; skos:inScheme perma:FeedingLevels ; skos:topConceptOf perma:FeedingLevels ;\n    skos:prefLabel \"Soil builder\"@en , \"Bodenverbesserer\"@de , \"Améliorant\"@fr ;\n    skos:definition \"Leaves the soil richer than it found it: legumes, with the bacteria on their roots, bring in nitrogen.\"@en .\n\nperma:RootDepths a skos:ConceptScheme ;\n    skos:prefLabel \"Root depths\"@en , \"Wurzeltiefen\"@de , \"Profondeurs d'enracinement\"@fr ;\n    skos:hasTopConcept perma:ShallowRoot , perma:MediumRoot , perma:DeepRoot .\nperma:ShallowRoot a skos:Concept ; skos:inScheme perma:RootDepths ; skos:topConceptOf perma:RootDepths ;\n    skos:prefLabel \"Shallow\"@en , \"Flach\"@de , \"Superficiel\"@fr .\nperma:MediumRoot a skos:Concept ; skos:inScheme perma:RootDepths ; skos:topConceptOf perma:RootDepths ;\n    skos:prefLabel \"Medium\"@en , \"Mittel\"@de , \"Moyen\"@fr .\nperma:DeepRoot a skos:Concept ; skos:inScheme perma:RootDepths ; skos:topConceptOf perma:RootDepths ;\n    skos:prefLabel \"Deep\"@en , \"Tief\"@de , \"Profond\"@fr .\n\nperma:SoilGifts a skos:ConceptScheme ;\n    skos:prefLabel \"What a crop gives\"@en , \"Was eine Kultur gibt\"@de , \"Ce qu'une culture apporte\"@fr ;\n    skos:hasTopConcept perma:FixesNitrogen , perma:ConfusesPests , perma:CoversSoil , perma:FeedsPollinators , perma:LoosensSoil .\nperma:FixesNitrogen a skos:Concept ; skos:inScheme perma:SoilGifts ; skos:topConceptOf perma:SoilGifts ;\n    skos:prefLabel \"Fixes nitrogen\"@en , \"Bindet Stickstoff\"@de , \"Fixe l'azote\"@fr .\nperma:ConfusesPests a skos:Concept ; skos:inScheme perma:SoilGifts ; skos:topConceptOf perma:SoilGifts ;\n    skos:prefLabel \"Confuses pests\"@en , \"Verwirrt Schädlinge\"@de , \"Déroute les ravageurs\"@fr ;\n    skos:definition \"A strong scent that hides its neighbours from the insects looking for them.\"@en .\nperma:CoversSoil a skos:Concept ; skos:inScheme perma:SoilGifts ; skos:topConceptOf perma:SoilGifts ;\n    skos:prefLabel \"Covers the soil\"@en , \"Bedeckt den Boden\"@de , \"Couvre le sol\"@fr .\nperma:FeedsPollinators a skos:Concept ; skos:inScheme perma:SoilGifts ; skos:topConceptOf perma:SoilGifts ;\n    skos:prefLabel \"Feeds pollinators\"@en , \"Nährt Bestäuber\"@de , \"Nourrit les pollinisateurs\"@fr .\nperma:LoosensSoil a skos:Concept ; skos:inScheme perma:SoilGifts ; skos:topConceptOf perma:SoilGifts ;\n    skos:prefLabel \"Loosens the soil\"@en , \"Lockert den Boden\"@de , \"Ameublit le sol\"@fr .\n\n@prefix perma: <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix skos:  <http://www.w3.org/2004/02/skos/core#> .\n\n# ============================================================\n# perma-core, habitat concept schemes, v0.1. New kinds are data.\n# ============================================================\n\nperma:ZoneKinds a skos:ConceptScheme ;\n    skos:prefLabel \"Kinds of area\"@en , \"Arten von Bereichen\"@de , \"Types de zone\"@fr ;\n    skos:hasTopConcept perma:RoofZone , perma:GroundZone , perma:BalconyZone , perma:GreenhouseZone .\nperma:RoofZone a skos:Concept ; skos:inScheme perma:ZoneKinds ; skos:topConceptOf perma:ZoneKinds ;\n    skos:prefLabel \"Roof\"@en , \"Dach\"@de , \"Toit\"@fr .\nperma:GroundZone a skos:Concept ; skos:inScheme perma:ZoneKinds ; skos:topConceptOf perma:ZoneKinds ;\n    skos:prefLabel \"Garden ground\"@en , \"Gartenboden\"@de , \"Pleine terre\"@fr .\nperma:BalconyZone a skos:Concept ; skos:inScheme perma:ZoneKinds ; skos:topConceptOf perma:ZoneKinds ;\n    skos:prefLabel \"Balcony or terrace\"@en , \"Balkon oder Terrasse\"@de , \"Balcon ou terrasse\"@fr .\nperma:GreenhouseZone a skos:Concept ; skos:inScheme perma:ZoneKinds ; skos:topConceptOf perma:ZoneKinds ;\n    skos:prefLabel \"Greenhouse\"@en , \"Gewächshaus\"@de , \"Serre\"@fr .\n\nperma:Exposures a skos:ConceptScheme ;\n    skos:prefLabel \"Exposure\"@en , \"Lage\"@de , \"Exposition\"@fr ;\n    skos:hasTopConcept perma:FullSun , perma:HalfShade , perma:Shade , perma:Windy .\nperma:FullSun a skos:Concept ; skos:inScheme perma:Exposures ; skos:topConceptOf perma:Exposures ;\n    skos:prefLabel \"Full sun\"@en , \"Volle Sonne\"@de , \"Plein soleil\"@fr .\nperma:HalfShade a skos:Concept ; skos:inScheme perma:Exposures ; skos:topConceptOf perma:Exposures ;\n    skos:prefLabel \"Half shade\"@en , \"Halbschatten\"@de , \"Mi-ombre\"@fr .\nperma:Shade a skos:Concept ; skos:inScheme perma:Exposures ; skos:topConceptOf perma:Exposures ;\n    skos:prefLabel \"Shade\"@en , \"Schatten\"@de , \"Ombre\"@fr .\nperma:Windy a skos:Concept ; skos:inScheme perma:Exposures ; skos:topConceptOf perma:Exposures ;\n    skos:prefLabel \"Windy\"@en , \"Windig\"@de , \"Venté\"@fr .\n\nperma:CellStatuses a skos:ConceptScheme ;\n    skos:prefLabel \"Cell status\"@en , \"Zellstand\"@de , \"État de la case\"@fr ;\n    skos:hasTopConcept perma:CellPlanned , perma:CellSown , perma:CellGrowing , perma:CellHarvested , perma:CellLost .\nperma:CellPlanned a skos:Concept ; skos:inScheme perma:CellStatuses ; skos:topConceptOf perma:CellStatuses ;\n    skos:prefLabel \"Planned\"@en , \"Geplant\"@de , \"Prévu\"@fr .\nperma:CellSown a skos:Concept ; skos:inScheme perma:CellStatuses ; skos:topConceptOf perma:CellStatuses ;\n    skos:prefLabel \"Sown or planted\"@en , \"Gesät oder gepflanzt\"@de , \"Semé ou planté\"@fr .\nperma:CellGrowing a skos:Concept ; skos:inScheme perma:CellStatuses ; skos:topConceptOf perma:CellStatuses ;\n    skos:prefLabel \"Growing\"@en , \"Wächst\"@de , \"En croissance\"@fr .\nperma:CellHarvested a skos:Concept ; skos:inScheme perma:CellStatuses ; skos:topConceptOf perma:CellStatuses ;\n    skos:prefLabel \"Harvested\"@en , \"Geerntet\"@de , \"Récolté\"@fr .\nperma:CellLost a skos:Concept ; skos:inScheme perma:CellStatuses ; skos:topConceptOf perma:CellStatuses ;\n    skos:prefLabel \"Lost\"@en , \"Ausgefallen\"@de , \"Perdu\"@fr ;\n    skos:definition \"Did not come up, froze or dried out: the cell is free to sow again (docs/adr/0029).\"@en .\n\nperma:PeriodKinds a skos:ConceptScheme ;\n    skos:prefLabel \"Kind of period\"@en , \"Art des Abschnitts\"@de , \"Type de période\"@fr ;\n    skos:hasTopConcept perma:GrowingKind , perma:RestKind .\nperma:GrowingKind a skos:Concept ; skos:inScheme perma:PeriodKinds ; skos:topConceptOf perma:PeriodKinds ;\n    skos:prefLabel \"Growing\"@en , \"Anbau\"@de , \"Culture\"@fr ;\n    skos:definition \"From sowing to harvest: the bed is planted with the period's plant sets.\"@en .\nperma:RestKind a skos:Concept ; skos:inScheme perma:PeriodKinds ; skos:topConceptOf perma:PeriodKinds ;\n    skos:prefLabel \"Rest\"@en , \"Ruhe\"@de , \"Repos\"@fr ;\n    skos:definition \"Winter or maintenance: nothing is sown but a cover crop; the worm box goes on in its winter care.\"@en .\n\nperma:SurfaceCategories a skos:ConceptScheme ;\n    skos:prefLabel \"Surface categories\"@en , \"Flächenarten\"@de , \"Catégories de surface\"@fr ;\n    skos:hasTopConcept perma:RectangleBedSurface , perma:BedFarmSurface .\nperma:RectangleBedSurface a skos:Concept ; skos:inScheme perma:SurfaceCategories ; skos:topConceptOf perma:SurfaceCategories ;\n    skos:prefLabel \"Rectangle bed\"@en , \"Rechteckbeet\"@de , \"Planche rectangulaire\"@fr ;\n    skos:definition \"One rectangular bed of square cells, up to 30 m long and 10 m wide; planted by cells (docs/adr/0027).\"@en .\nperma:BedFarmSurface a skos:Concept ; skos:inScheme perma:SurfaceCategories ; skos:topConceptOf perma:SurfaceCategories ;\n    skos:prefLabel \"Farm of beds\"@en , \"Beetfeld\"@de , \"Ensemble de planches\"@fr ;\n    skos:definition \"Rectangle beds of one size in rows, with paths between them, up to 50 beds; plant sets are shared out over the beds.\"@en .\n# Greenhouses and food forests come once beds and farms of beds are right (docs/adr/0028).\n\nperma:SubstrateKinds a skos:ConceptScheme ;\n    skos:prefLabel \"Substrates\"@en , \"Substrate\"@de , \"Substrats\"@fr ;\n    skos:hasTopConcept perma:LightweightRoofSubstrate , perma:GardenSoil , perma:PottingCompost .\nperma:LightweightRoofSubstrate a skos:Concept ; skos:inScheme perma:SubstrateKinds ; skos:topConceptOf perma:SubstrateKinds ;\n    skos:prefLabel \"Lightweight roof substrate\"@en , \"Leichtes Dachsubstrat\"@de , \"Substrat léger pour toiture\"@fr ;\n    skos:definition \"A mineral mix made for green roofs (expanded clay or shale, pumice, some compost): lighter when wet than soil.\"@en .\nperma:GardenSoil a skos:Concept ; skos:inScheme perma:SubstrateKinds ; skos:topConceptOf perma:SubstrateKinds ;\n    skos:prefLabel \"Garden soil\"@en , \"Gartenerde\"@de , \"Terre de jardin\"@fr ;\n    skos:definition \"Topsoil, with or without compost: the heaviest choice when wet.\"@en .\nperma:PottingCompost a skos:Concept ; skos:inScheme perma:SubstrateKinds ; skos:topConceptOf perma:SubstrateKinds ;\n    skos:prefLabel \"Potting compost\"@en , \"Blumenerde\"@de , \"Terreau\"@fr ;\n    skos:definition \"Peat-free potting mix: light, but it settles and has to be topped up.\"@en .\n\nperma:GuildTypes a skos:ConceptScheme ;\n    skos:prefLabel \"Guild types\"@en , \"Gildentypen\"@de , \"Types de guilde\"@fr ;\n    skos:hasTopConcept perma:WormBed5 .\nperma:WormBed5 a skos:Concept ; skos:inScheme perma:GuildTypes ; skos:topConceptOf perma:GuildTypes ;\n    skos:prefLabel \"WormBed5\"@en , \"WormBed5\"@de , \"WormBed5\"@fr ;\n    skos:definition \"A flat growing bed with a worm compost box at one end, whose liquid reaches the plants from below, worked by a gantry robot (docs/specs/roofbed-system.md).\"@en .\n\nperma:RobotModels a skos:ConceptScheme ;\n    skos:prefLabel \"Robots\"@en , \"Roboter\"@de , \"Robots\"@fr ;\n    skos:hasTopConcept perma:Gantry5Gen1 .\nperma:Gantry5Gen1 a skos:Concept ; skos:inScheme perma:RobotModels ; skos:topConceptOf perma:RobotModels ;\n    skos:prefLabel \"Gantry5-gen1\"@en , \"Gantry5-gen1\"@de , \"Gantry5-gen1\"@fr ;\n    skos:definition \"Gantry5, first generation: three axes over a bed, with a seeder, a watering nozzle, a soil probe, a camera and a scoop for the worm box (docs/specs/roofbed-robot.md).\"@en .\n\n# ------------------------------------------------------------ water (v0.2, docs/adr/0025)\n\nperma:WaterStoreKinds a skos:ConceptScheme ;\n    skos:prefLabel \"Water stores\"@en , \"Wasserspeicher\"@de , \"Réserves d'eau\"@fr ;\n    skos:hasTopConcept perma:RainBarrel , perma:TankPipes , perma:WormBoxSump , perma:WormBoxBin , perma:GardenTank .\nperma:RainBarrel a skos:Concept ; skos:inScheme perma:WaterStoreKinds ; skos:topConceptOf perma:WaterStoreKinds ;\n    skos:prefLabel \"Rain barrel\"@en , \"Regentonne\"@de , \"Récupérateur d'eau de pluie\"@fr ;\n    skos:definition \"Collects rain from a catchment; a tap at its foot lets it on.\"@en .\nperma:TankPipes a skos:Concept ; skos:inScheme perma:WaterStoreKinds ; skos:topConceptOf perma:WaterStoreKinds ;\n    skos:prefLabel \"Tank pipes\"@en , \"Tankrohre\"@de , \"Tuyaux-réservoir\"@fr ;\n    skos:definition \"The drain pipes under a wicking bed's substrate: the soil draws their water up from below.\"@en .\nperma:WormBoxSump a skos:Concept ; skos:inScheme perma:WaterStoreKinds ; skos:topConceptOf perma:WaterStoreKinds ;\n    skos:prefLabel \"Worm box sump\"@en , \"Sumpf der Wurmkiste\"@de , \"Puisard du bac à vers\"@fr ;\n    skos:definition \"The worm box's lower bin: it catches the liquid that drips from the worms' bin.\"@en .\nperma:WormBoxBin a skos:Concept ; skos:inScheme perma:WaterStoreKinds ; skos:topConceptOf perma:WaterStoreKinds ;\n    skos:prefLabel \"Worm box bin\"@en , \"Arbeitskiste der Wurmkiste\"@de , \"Bac de travail du bac à vers\"@fr ;\n    skos:definition \"The worm box's working bin, as a place water goes to: a mist line under its lid waters the bedding with clean water, the box closed. It stores nothing; its moisture probe says when it needs some.\"@en .\nperma:GardenTank a skos:Concept ; skos:inScheme perma:WaterStoreKinds ; skos:topConceptOf perma:WaterStoreKinds ;\n    skos:prefLabel \"Garden tank\"@en , \"Gartentank\"@de , \"Cuve de jardin\"@fr ;\n    skos:definition \"A tank elsewhere on the site, e.g. in the garden by the fruit trees: it takes what the guild's own bed does not need.\"@en .\n\nperma:WaterKinds a skos:ConceptScheme ;\n    skos:prefLabel \"Kinds of water\"@en , \"Wasserarten\"@de , \"Types d'eau\"@fr ;\n    skos:hasTopConcept perma:CleanWater , perma:WormLiquid .\nperma:CleanWater a skos:Concept ; skos:inScheme perma:WaterKinds ; skos:topConceptOf perma:WaterKinds ;\n    skos:prefLabel \"Clean water\"@en , \"Sauberes Wasser\"@de , \"Eau propre\"@fr ;\n    skos:definition \"Rain or tap water: it may go on leaves and seeds.\"@en .\nperma:WormLiquid a skos:Concept ; skos:inScheme perma:WaterKinds ; skos:topConceptOf perma:WaterKinds ;\n    skos:prefLabel \"Worm liquid\"@en , \"Wurmflüssigkeit\"@de , \"Liquide du lombricomposteur\"@fr ;\n    skos:definition \"Drainage from fresh worm compost: rich, but never on leaves of anything eaten raw. Given below the surface only.\"@en .\n\nperma:ValveKinds a skos:ConceptScheme ;\n    skos:prefLabel \"Valves\"@en , \"Ventile\"@de , \"Vannes\"@fr ;\n    skos:hasTopConcept perma:ManualTap , perma:EdgeValve .\nperma:ManualTap a skos:Concept ; skos:inScheme perma:ValveKinds ; skos:topConceptOf perma:ValveKinds ;\n    skos:prefLabel \"Manual tap\"@en , \"Handhahn\"@de , \"Robinet manuel\"@fr ;\n    skos:definition \"A person opens and closes it; the edge proposes when.\"@en .\nperma:EdgeValve a skos:Concept ; skos:inScheme perma:ValveKinds ; skos:topConceptOf perma:ValveKinds ;\n    skos:prefLabel \"Edge valve\"@en , \"Edge-Ventil\"@de , \"Vanne pilotée\"@fr ;\n    skos:definition \"A motor or solenoid valve the guild's edge opens, after a person confirmed the proposal.\"@en .\n\n@prefix perma: <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix skos:  <http://www.w3.org/2004/02/skos/core#> .\n\n# ============================================================\n# perma-core, learning concept schemes, v0.1 (docs/adr/0026).\n# ============================================================\n\nperma:CyclePhases a skos:ConceptScheme ;\n    skos:prefLabel \"Phases of a learning cycle\"@en , \"Phasen eines Lernzyklus\"@de , \"Phases d'un cycle d'apprentissage\"@fr ;\n    skos:hasTopConcept perma:PlanPhase , perma:DoPhase , perma:CheckPhase , perma:ActPhase .\nperma:PlanPhase a skos:Concept ; skos:inScheme perma:CyclePhases ; skos:topConceptOf perma:CyclePhases ;\n    skos:prefLabel \"Plan\"@en , \"Planen\"@de , \"Planifier\"@fr ;\n    skos:definition \"Say what is expected, how sure, and how it will be measured.\"@en .\nperma:DoPhase a skos:Concept ; skos:inScheme perma:CyclePhases ; skos:topConceptOf perma:CyclePhases ;\n    skos:prefLabel \"Do\"@en , \"Umsetzen\"@de , \"Faire\"@fr ;\n    skos:definition \"Run the guild and measure, as planned.\"@en .\nperma:CheckPhase a skos:Concept ; skos:inScheme perma:CyclePhases ; skos:topConceptOf perma:CyclePhases ;\n    skos:prefLabel \"Check\"@en , \"Prüfen\"@de , \"Vérifier\"@fr ;\n    skos:definition \"Set the measurements beside the hypotheses: which hold, which fail.\"@en .\nperma:ActPhase a skos:Concept ; skos:inScheme perma:CyclePhases ; skos:topConceptOf perma:CyclePhases ;\n    skos:prefLabel \"Act\"@en , \"Handeln\"@de , \"Agir\"@fr ;\n    skos:definition \"Change what the checks call for, and start the next cycle with the new numbers.\"@en .\n\nperma:Verdicts a skos:ConceptScheme ;\n    skos:prefLabel \"Verdicts\"@en , \"Urteile\"@de , \"Verdicts\"@fr ;\n    skos:hasTopConcept perma:VerdictOpen , perma:VerdictHolds , perma:VerdictFails .\nperma:VerdictOpen a skos:Concept ; skos:inScheme perma:Verdicts ; skos:topConceptOf perma:Verdicts ;\n    skos:prefLabel \"Open\"@en , \"Offen\"@de , \"Ouverte\"@fr ;\n    skos:definition \"Not enough checks yet.\"@en .\nperma:VerdictHolds a skos:Concept ; skos:inScheme perma:Verdicts ; skos:topConceptOf perma:Verdicts ;\n    skos:prefLabel \"Holds\"@en , \"Bestätigt\"@de , \"Confirmée\"@fr ;\n    skos:definition \"The measurements lie within the range.\"@en .\nperma:VerdictFails a skos:Concept ; skos:inScheme perma:Verdicts ; skos:topConceptOf perma:Verdicts ;\n    skos:prefLabel \"Fails\"@en , \"Widerlegt\"@de , \"Réfutée\"@fr ;\n    skos:definition \"Outside the range for two checks running, or at the season's end.\"@en .\n";
export const LIBRARY = "@prefix perma: <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix id:    <https://permaculture.digitalhome.cloud/id/> .\n@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix dwc:   <http://rs.tdwg.org/dwc/terms/> .\n\n# The shared crop library, v0.3: the crops of the recipes, salad crops for a roof bed, fruit trees, and what each\n# herbaceous crop takes from the bed and gives to it (at the end of the file). The same for\n# every project; when and where they grow is each site's calendar.\n# Names: English, French, German and Latin (rdfs:label @en @fr @de @la). GBIF links are in\n# crops-gbif.ttl (generated by tools/gbif_link.py).\n# keeps: the ways each part can be kept and for how many months after the harvest (approximate).\n\nid:crop-courgette a perma:Crop ;\n    rdfs:label \"Courgette\"@en , \"Zucchini\"@de , \"Courgette\"@fr , \"Cucurbita pepo\"@la ;\n    rdfs:comment \"The courgette group of the species; pumpkins and pâtissons are the same species and cross with it.\"@en ;\n    dwc:scientificName \"Cucurbita pepo\" ;\n    perma:sowingDepthMm 25 ; perma:seedsPerPoint 2 ; perma:germinationDays 7 ; perma:waterMmPerWeek 30.0 ;\n    perma:sowMinTempC 14.0 ; perma:plantOutMinNightC 10.0 ; perma:frostTender true ; perma:daysToHarvest 60 ; perma:spacingCm 80 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"every Cucurbita pepo: other courgettes, pumpkins, pâtissons, ornamental gourds\" ;\n        perma:isolationM 800.0 ; perma:seedViabilityYears 6 ; perma:selfSows false ;\n        rdfs:comment \"Or hand-pollinate a female flower and close it. Seed from a fruit left to mature on the plant about 8 weeks past eating size.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 8 ] ] .\n\nid:crop-onion a perma:Crop ;\n    rdfs:label \"Onion\"@en , \"Zwiebel\"@de , \"Oignon\"@fr , \"Allium cepa\"@la ;\n    dwc:scientificName \"Allium cepa\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 1 ; perma:germinationDays 12 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 7.0 ; perma:frostTender false ; perma:daysToHarvest 120 ; perma:spacingCm 10 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Biennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"every Allium cepa, including shallots\" ;\n        perma:isolationM 1000.0 ; perma:seedViabilityYears 2 ; perma:selfSows false ;\n        rdfs:comment \"Keep the best bulbs over winter, replant them in spring; seed heads ripen in summer of the second year. Seed is short-lived: renew every year or two.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Bulb ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Cellar ; perma:storageMonths 6 ] ] .\n\nid:crop-sweet-pepper a perma:Crop ;\n    rdfs:label \"Sweet pepper\"@en , \"Paprika\"@de , \"Poivron\"@fr , \"Capsicum annuum\"@la ;\n    rdfs:comment \"The sweet (non-pungent) group of the species; chillies are the same species.\"@en ;\n    dwc:scientificName \"Capsicum annuum\" ;\n    perma:sowingDepthMm 5 ; perma:seedsPerPoint 2 ; perma:germinationDays 12 ; perma:waterMmPerWeek 25.0 ;\n    perma:sowMinTempC 18.0 ; perma:plantOutMinNightC 12.0 ; perma:frostTender true ; perma:daysToHarvest 150 ; perma:spacingCm 40 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:SelfPollinating ;\n        perma:crossesWith \"every Capsicum annuum, chillies included (insects cross some flowers)\" ;\n        perma:isolationM 50.0 ; perma:seedViabilityYears 3 ; perma:selfSows false ;\n        rdfs:comment \"Seed from fully ripe (coloured) fruit; bag a few flowers if chillies grow nearby.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 8 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-dill a perma:Crop ;\n    rdfs:label \"Dill\"@en , \"Dill\"@de , \"Aneth\"@fr , \"Anethum graveolens\"@la ;\n    dwc:scientificName \"Anethum graveolens\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 3 ; perma:germinationDays 14 ; perma:waterMmPerWeek 15.0 ;\n    perma:sowMinTempC 10.0 ; perma:boltAboveC 27.0 ; perma:frostTender false ; perma:daysToHarvest 50 ; perma:spacingCm 20 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other dill varieties\" ;\n        perma:isolationM 800.0 ; perma:seedViabilityYears 3 ; perma:selfSows true ;\n        rdfs:comment \"Let a few plants flower and dry on the stem; the same seed is the spice. Self-sows readily.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] , [ perma:method perma:Frozen ; perma:storageMonths 6 ] ] ,\n                 [ perma:part perma:Seed ; perma:keeps [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-white-mustard a perma:Crop ;\n    rdfs:label \"White mustard\"@en , \"Weißer Senf\"@de , \"Moutarde blanche\"@fr , \"Sinapis alba\"@la ;\n    rdfs:comment \"Yellow mustard seed (graines de moutarde jaune) for pickles.\"@en ;\n    dwc:scientificName \"Sinapis alba\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 3 ; perma:germinationDays 5 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 5.0 ; perma:frostTender false ; perma:daysToHarvest 90 ; perma:spacingCm 10 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other Sinapis alba\" ;\n        perma:isolationM 800.0 ; perma:seedViabilityYears 4 ; perma:selfSows true ;\n        rdfs:comment \"The seed harvest for the kitchen is also the seed for next year: keep some back.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Seed ; perma:keeps [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-black-pepper a perma:Crop ;\n    rdfs:label \"Black pepper\"@en , \"Schwarzer Pfeffer\"@de , \"Poivre noir\"@fr , \"Piper nigrum\"@la ;\n    rdfs:comment \"A tropical vine: in the library so recipes can name it, but no temperate site has a calendar for it.\"@en ;\n    dwc:scientificName \"Piper nigrum\" ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Dried ; perma:storageMonths 24 ] ] .\n\n# ------------------------------------------------------------ added 2026-10-09: the second set of recipes\n\nid:crop-tomato a perma:Crop ;\n    rdfs:label \"Tomato\"@en , \"Tomate\"@de , \"Tomate\"@fr , \"Solanum lycopersicum\"@la ;\n    dwc:scientificName \"Solanum lycopersicum\" ;\n    perma:sowingDepthMm 5 ; perma:seedsPerPoint 2 ; perma:germinationDays 8 ; perma:waterMmPerWeek 30.0 ;\n    perma:sowMinTempC 16.0 ; perma:plantOutMinNightC 10.0 ; perma:frostTender true ; perma:daysToHarvest 120 ; perma:spacingCm 50 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ;\n        perma:lifeCycle perma:Annual ;\n        perma:pollination perma:SelfPollinating ;\n        perma:crossesWith \"other tomatoes, rarely (potato-leaf and old varieties more)\" ;\n        perma:isolationM 3.0 ;\n        perma:seedViabilityYears 5 ;\n        perma:selfSows false ;\n        rdfs:comment \"Seed from fully ripe fruit of open-pollinated varieties (not F1); ferment the pulp a few days, rinse, dry.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Bottled ; perma:storageMonths 12 ] , [ perma:method perma:Frozen ; perma:storageMonths 8 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-aubergine a perma:Crop ;\n    rdfs:label \"Aubergine\"@en , \"Aubergine\"@de , \"Aubergine\"@fr , \"Solanum melongena\"@la ;\n    dwc:scientificName \"Solanum melongena\" ;\n    perma:sowingDepthMm 5 ; perma:seedsPerPoint 2 ; perma:germinationDays 12 ; perma:waterMmPerWeek 30.0 ;\n    perma:sowMinTempC 20.0 ; perma:plantOutMinNightC 13.0 ; perma:frostTender true ; perma:daysToHarvest 150 ; perma:spacingCm 50 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ;\n        perma:lifeCycle perma:Annual ;\n        perma:pollination perma:SelfPollinating ;\n        perma:crossesWith \"other aubergines (insects cross some flowers)\" ;\n        perma:isolationM 15.0 ;\n        perma:seedViabilityYears 5 ;\n        perma:selfSows false ;\n        rdfs:comment \"Leave a fruit on the plant until it turns dull yellow-brown; scrape out the seed.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 6 ] ] .\n\nid:crop-garlic a perma:Crop ;\n    rdfs:label \"Garlic\"@en , \"Knoblauch\"@de , \"Ail\"@fr , \"Allium sativum\"@la ;\n    dwc:scientificName \"Allium sativum\" ;\n    perma:sowingDepthMm 40 ; perma:seedsPerPoint 1 ; perma:germinationDays 14 ; perma:waterMmPerWeek 15.0 ;\n    perma:sowMinTempC 5.0 ; perma:frostTender false ; perma:daysToHarvest 240 ; perma:spacingCm 12 ;\n    perma:seedSaving [ perma:propagation perma:FromCloves ;\n        perma:lifeCycle perma:Perennial ;\n        perma:selfSows false ;\n        rdfs:comment \"Grown as an annual: keep the biggest, healthiest bulbs and replant their outer cloves in autumn.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Bulb ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Cellar ; perma:storageMonths 8 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-basil a perma:Crop ;\n    rdfs:label \"Basil\"@en , \"Basilikum\"@de , \"Basilic\"@fr , \"Ocimum basilicum\"@la ;\n    dwc:scientificName \"Ocimum basilicum\" ;\n    perma:sowingDepthMm 3 ; perma:seedsPerPoint 3 ; perma:germinationDays 8 ; perma:waterMmPerWeek 25.0 ;\n    perma:sowMinTempC 16.0 ; perma:plantOutMinNightC 12.0 ; perma:frostTender true ; perma:daysToHarvest 70 ; perma:spacingCm 20 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed , perma:FromCuttings ;\n        perma:lifeCycle perma:Annual ;\n        perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other basils (Ocimum basilicum varieties)\" ;\n        perma:isolationM 50.0 ;\n        perma:seedViabilityYears 5 ;\n        perma:selfSows false ;\n        rdfs:comment \"Let a few plants flower; cut the dry flower stems and rub out the seed.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 6 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-thyme a perma:Crop ;\n    rdfs:label \"Thyme\"@en , \"Thymian\"@de , \"Thym\"@fr , \"Thymus vulgaris\"@la ;\n    rdfs:comment \"An evergreen perennial: leaves can be picked all year, best for drying just before flowering.\"@en ;\n    dwc:scientificName \"Thymus vulgaris\" ;\n    perma:sowingDepthMm 1 ; perma:seedsPerPoint 4 ; perma:germinationDays 14 ; perma:waterMmPerWeek 10.0 ;\n    perma:sowMinTempC 13.0 ; perma:frostTender false ; perma:daysToHarvest 120 ; perma:spacingCm 25 ;\n    perma:seedSaving [ perma:propagation perma:FromCuttings , perma:ByDivision , perma:FromSeed ;\n        perma:lifeCycle perma:Perennial ;\n        perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other Thymus vulgaris\" ;\n        perma:seedViabilityYears 3 ;\n        perma:selfSows false ;\n        rdfs:comment \"Easiest kept by cuttings or division of a good plant; renew every 4-5 years when it gets woody.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-rosemary a perma:Crop ;\n    rdfs:label \"Rosemary\"@en , \"Rosmarin\"@de , \"Romarin\"@fr , \"Salvia rosmarinus\"@la ;\n    rdfs:comment \"Formerly Rosmarinus officinalis. Evergreen: leaves all year.\"@en ;\n    dwc:scientificName \"Salvia rosmarinus\" ;\n    perma:sowingDepthMm 2 ; perma:seedsPerPoint 3 ; perma:germinationDays 21 ; perma:waterMmPerWeek 10.0 ;\n    perma:sowMinTempC 15.0 ; perma:frostTender false ; perma:daysToHarvest 365 ; perma:spacingCm 60 ;\n    perma:seedSaving [ perma:propagation perma:FromCuttings ;\n        perma:lifeCycle perma:Perennial ;\n        perma:selfSows false ;\n        rdfs:comment \"Take cuttings of non-flowering shoots in late summer.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-bay-laurel a perma:Crop ;\n    rdfs:label \"Bay laurel\"@en , \"Echter Lorbeer\"@de , \"Laurier-sauce\"@fr , \"Laurus nobilis\"@la ;\n    rdfs:comment \"Evergreen shrub or small tree: leaves all year.\"@en ;\n    dwc:scientificName \"Laurus nobilis\" ;\n    perma:seedSaving [ perma:propagation perma:FromCuttings ;\n        perma:lifeCycle perma:Perennial ;\n        perma:selfSows false ;\n        rdfs:comment \"Semi-ripe cuttings in summer, or suckers from the base.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-white-cabbage a perma:Crop ;\n    rdfs:label \"White cabbage\"@en , \"Weißkohl\"@de , \"Chou blanc\"@fr , \"Brassica oleracea\"@la ;\n    rdfs:comment \"The white headed cabbage group (capitata) of the species; kale, broccoli and cauliflower are the same species and cross with it.\"@en ;\n    dwc:scientificName \"Brassica oleracea\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 2 ; perma:germinationDays 7 ; perma:waterMmPerWeek 30.0 ;\n    perma:sowMinTempC 7.0 ; perma:frostTender false ; perma:daysToHarvest 120 ; perma:spacingCm 50 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ;\n        perma:lifeCycle perma:Biennial ;\n        perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"every Brassica oleracea: other cabbages, kale, broccoli, cauliflower, kohlrabi\" ;\n        perma:isolationM 800.0 ;\n        perma:seedViabilityYears 5 ;\n        perma:selfSows false ;\n        rdfs:comment \"Keep the best heads over winter, replant in spring; seed pods ripen in summer of the second year.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Cellar ; perma:storageMonths 4 ] , [ perma:method perma:Fermented ; perma:storageMonths 6 ] ] .\n\nid:crop-caraway a perma:Crop ;\n    rdfs:label \"Caraway\"@en , \"Kümmel\"@de , \"Carvi\"@fr , \"Carum carvi\"@la ;\n    dwc:scientificName \"Carum carvi\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 3 ; perma:germinationDays 14 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 8.0 ; perma:frostTender false ; perma:daysToHarvest 400 ; perma:spacingCm 20 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ;\n        perma:lifeCycle perma:Biennial ;\n        perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other caraway\" ;\n        perma:isolationM 800.0 ;\n        perma:seedViabilityYears 2 ;\n        perma:selfSows true ;\n        rdfs:comment \"Flowers in its second year; the seed for the kitchen is the seed for sowing.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Seed ; perma:keeps [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-apple a perma:Crop ;\n    rdfs:label \"Apple\"@en , \"Apfel\"@de , \"Pommier (pomme)\"@fr , \"Malus domestica\"@la ;\n    dwc:scientificName \"Malus domestica\" ;\n    perma:growthForm perma:Tree ;\n    perma:typicalWindow [ perma:activity perma:Flowering ; perma:fromMonth 4 ; perma:toMonth 5 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:Harvest ; perma:part perma:Fruit ; perma:fromMonth 8 ; perma:toMonth 10 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:WinterPrune ; perma:fromMonth 12 ; perma:toMonth 2 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:SummerPrune ; perma:fromMonth 7 ; perma:toMonth 8 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ;\n    perma:seedSaving [ perma:propagation perma:ByGrafting ;\n        perma:lifeCycle perma:Perennial ;\n        perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other apple and crab apple varieties (needed: most apples need a pollinator variety nearby)\" ;\n        perma:selfSows false ;\n        rdfs:comment \"Apples do not come true from seed: keep a variety by grafting scions onto a rootstock in late winter.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Cellar ; perma:storageMonths 5 ] , [ perma:method perma:Bottled ; perma:storageMonths 12 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-walnut a perma:Crop ;\n    rdfs:label \"Walnut\"@en , \"Walnuss\"@de , \"Noyer (noix)\"@fr , \"Juglans regia\"@la ;\n    rdfs:comment \"The green fruit (late June) is for vin de noix; the ripe nut (autumn) is the kernel, stored dry.\"@en ;\n    dwc:scientificName \"Juglans regia\" ;\n    perma:growthForm perma:Tree ;\n    perma:typicalWindow [ perma:activity perma:Flowering ; perma:fromMonth 4 ; perma:toMonth 5 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:Harvest ; perma:part perma:Seed ; perma:fromMonth 9 ; perma:toMonth 10 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:SummerPrune ; perma:fromMonth 8 ; perma:toMonth 9 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ;\n    perma:seedSaving [ perma:propagation perma:ByGrafting , perma:FromSeed ;\n        perma:lifeCycle perma:Perennial ;\n        perma:pollination perma:WindPollinated ;\n        perma:crossesWith \"other walnuts\" ;\n        perma:seedViabilityYears 1 ;\n        perma:selfSows false ;\n        rdfs:comment \"Named varieties (Franquette) are grafted; seedlings vary. Nuts for sowing must not dry out.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Macerated ; perma:storageMonths 36 ] ] ,\n                 [ perma:part perma:Seed ; perma:keeps [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\n# ------------------------------------------------------------ salad and roof-bed crops (v0.2)\n\nid:crop-lettuce a perma:Crop ;\n    rdfs:label \"Lettuce\"@en , \"Salat\"@de , \"Laitue\"@fr , \"Lactuca sativa\"@la ;\n    rdfs:comment \"Sown little and often for a steady supply; bolts in heat.\"@en ;\n    dwc:scientificName \"Lactuca sativa\" ;\n    perma:sowingDepthMm 5 ; perma:seedsPerPoint 3 ; perma:germinationDays 7 ; perma:waterMmPerWeek 25.0 ;\n    perma:sowMinTempC 5.0 ; perma:boltAboveC 25.0 ; perma:frostTender false ; perma:daysToHarvest 55 ; perma:spacingCm 25 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:SelfPollinating ;\n        perma:crossesWith \"other lettuces, rarely\" ; perma:isolationM 3.0 ; perma:seedViabilityYears 4 ; perma:selfSows false ;\n        rdfs:comment \"Let the best plant bolt; cut the fluffy heads when most seeds are ripe.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] ] .\n\nid:crop-rocket a perma:Crop ;\n    rdfs:label \"Rocket\"@en , \"Rucola\"@de , \"Roquette\"@fr , \"Eruca vesicaria\"@la ;\n    rdfs:comment \"Salad rocket; quick, and runs to seed fast in summer.\"@en ;\n    dwc:scientificName \"Eruca vesicaria\" ;\n    perma:sowingDepthMm 5 ; perma:seedsPerPoint 3 ; perma:germinationDays 6 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 5.0 ; perma:boltAboveC 24.0 ; perma:frostTender false ; perma:daysToHarvest 35 ; perma:spacingCm 10 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other Eruca vesicaria\" ; perma:isolationM 200.0 ; perma:seedViabilityYears 4 ; perma:selfSows true ;\n        rdfs:comment \"Seed pods ripen weeks after flowering; it often sows itself.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] ] .\n\nid:crop-radish a perma:Crop ;\n    rdfs:label \"Radish\"@en , \"Radieschen\"@de , \"Radis\"@fr , \"Raphanus sativus\"@la ;\n    rdfs:comment \"Small summer radish; ready in a month.\"@en ;\n    dwc:scientificName \"Raphanus sativus\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 2 ; perma:germinationDays 5 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 5.0 ; perma:boltAboveC 24.0 ; perma:frostTender false ; perma:daysToHarvest 30 ; perma:spacingCm 5 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"every Raphanus sativus, including winter radish and wild radish\" ; perma:isolationM 800.0 ; perma:seedViabilityYears 5 ; perma:selfSows false ;\n        rdfs:comment \"Leave a few roots to flower; the green pods are edible too.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Root ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] ] .\n\nid:crop-spinach a perma:Crop ;\n    rdfs:label \"Spinach\"@en , \"Spinat\"@de , \"Épinard\"@fr , \"Spinacia oleracea\"@la ;\n    rdfs:comment \"Spring and autumn crop; bolts in long warm days.\"@en ;\n    dwc:scientificName \"Spinacia oleracea\" ;\n    perma:sowingDepthMm 20 ; perma:seedsPerPoint 2 ; perma:germinationDays 10 ; perma:waterMmPerWeek 25.0 ;\n    perma:sowMinTempC 4.0 ; perma:boltAboveC 22.0 ; perma:frostTender false ; perma:daysToHarvest 45 ; perma:spacingCm 10 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:WindPollinated ;\n        perma:crossesWith \"every Spinacia oleracea\" ; perma:isolationM 1000.0 ; perma:seedViabilityYears 3 ; perma:selfSows false ;\n        rdfs:comment \"Male and female plants: keep enough plants (20 or more) for good seed.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 8 ] ] .\n\nid:crop-swiss-chard a perma:Crop ;\n    rdfs:label \"Swiss chard\"@en , \"Mangold\"@de , \"Blette (poirée)\"@fr , \"Beta vulgaris\"@la ;\n    rdfs:comment \"Leaf beet; picked leaf by leaf from early summer to the frosts.\"@en ;\n    dwc:scientificName \"Beta vulgaris\" ;\n    perma:sowingDepthMm 20 ; perma:seedsPerPoint 1 ; perma:germinationDays 10 ; perma:waterMmPerWeek 25.0 ;\n    perma:sowMinTempC 8.0 ; perma:frostTender false ; perma:daysToHarvest 60 ; perma:spacingCm 30 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Biennial ; perma:pollination perma:WindPollinated ;\n        perma:crossesWith \"every Beta vulgaris: beetroot, sugar beet, other chards\" ; perma:isolationM 1000.0 ; perma:seedViabilityYears 5 ; perma:selfSows false ;\n        rdfs:comment \"Overwinters and flowers in its second year; beet pollen travels far.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 8 ] ] .\n\nid:crop-spring-onion a perma:Crop ;\n    rdfs:label \"Spring onion\"@en , \"Frühlingszwiebel\"@de , \"Ciboule\"@fr , \"Allium fistulosum\"@la ;\n    rdfs:comment \"Welsh onion: green leaves and white stems, without a bulb.\"@en ;\n    dwc:scientificName \"Allium fistulosum\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 3 ; perma:germinationDays 12 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 7.0 ; perma:frostTender false ; perma:daysToHarvest 70 ; perma:spacingCm 5 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Perennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other Allium fistulosum\" ; perma:isolationM 800.0 ; perma:seedViabilityYears 2 ; perma:selfSows false ;\n        rdfs:comment \"Flowers from the second year; seed is short-lived.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] ] .\n\nid:crop-chives a perma:Crop ;\n    rdfs:label \"Chives\"@en , \"Schnittlauch\"@de , \"Ciboulette\"@fr , \"Allium schoenoprasum\"@la ;\n    rdfs:comment \"Perennial clumps; cut again and again, divide every few years.\"@en ;\n    dwc:scientificName \"Allium schoenoprasum\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 4 ; perma:germinationDays 14 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 10.0 ; perma:frostTender false ; perma:daysToHarvest 90 ; perma:spacingCm 20 ;\n    perma:seedSaving [ perma:propagation perma:ByDivision ; perma:lifeCycle perma:Perennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other chives\" ; perma:seedViabilityYears 2 ; perma:selfSows true ;\n        rdfs:comment \"Easiest kept by dividing clumps in spring; flowers are edible.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 6 ] , [ perma:method perma:Dried ; perma:storageMonths 6 ] ] .\n\nid:crop-parsley a perma:Crop ;\n    rdfs:label \"Parsley\"@en , \"Petersilie\"@de , \"Persil\"@fr , \"Petroselinum crispum\"@la ;\n    rdfs:comment \"Slow to germinate; overwinters and bolts in its second spring.\"@en ;\n    dwc:scientificName \"Petroselinum crispum\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 3 ; perma:germinationDays 21 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 8.0 ; perma:frostTender false ; perma:daysToHarvest 75 ; perma:spacingCm 15 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Biennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"every Petroselinum crispum, including root parsley\" ; perma:isolationM 300.0 ; perma:seedViabilityYears 3 ; perma:selfSows true ;\n        rdfs:comment \"Flowers in its second summer.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 6 ] , [ perma:method perma:Dried ; perma:storageMonths 6 ] ] .\n\n# ------------------------------------------------------------ fruit trees (v0.2)\n\nid:crop-pear a perma:Crop ;\n    rdfs:label \"Pear\"@en , \"Birne\"@de , \"Poirier (poire)\"@fr , \"Pyrus communis\"@la ;\n    rdfs:comment \"Most pears need a pollinator variety nearby; summer pears are picked just before ripe.\"@en ;\n    dwc:scientificName \"Pyrus communis\" ;\n    perma:growthForm perma:Tree ;\n    perma:typicalWindow [ perma:activity perma:Flowering ; perma:fromMonth 4 ; perma:toMonth 4 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:Harvest ; perma:part perma:Fruit ; perma:fromMonth 8 ; perma:toMonth 10 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:WinterPrune ; perma:fromMonth 12 ; perma:toMonth 2 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:SummerPrune ; perma:fromMonth 7 ; perma:toMonth 8 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ;\n    perma:seedSaving [ perma:propagation perma:ByGrafting ; perma:lifeCycle perma:Perennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other pear varieties (most pears need a pollinator)\" ; perma:selfSows false ;\n        rdfs:comment \"Pears do not come true from seed: graft scions onto pear or quince rootstock in late winter.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Cellar ; perma:storageMonths 3 ] , [ perma:method perma:Bottled ; perma:storageMonths 12 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-plum a perma:Crop ;\n    rdfs:label \"Plum\"@en , \"Pflaume\"@de , \"Prunier (prune)\"@fr , \"Prunus domestica\"@la ;\n    rdfs:comment \"Includes greengages and mirabelles; pruned in summer only (silver leaf).\"@en ;\n    dwc:scientificName \"Prunus domestica\" ;\n    perma:growthForm perma:Tree ;\n    perma:typicalWindow [ perma:activity perma:Flowering ; perma:fromMonth 3 ; perma:toMonth 4 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:Harvest ; perma:part perma:Fruit ; perma:fromMonth 8 ; perma:toMonth 9 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:SummerPrune ; perma:fromMonth 6 ; perma:toMonth 7 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ;\n    perma:seedSaving [ perma:propagation perma:ByGrafting ; perma:lifeCycle perma:Perennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other plums and gages; many varieties are self-fertile\" ; perma:selfSows false ;\n        rdfs:comment \"Graft onto St Julien or Myrobalan in spring; suckers of own-root trees also come true.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 10 ] , [ perma:method perma:Bottled ; perma:storageMonths 12 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\nid:crop-sweet-cherry a perma:Crop ;\n    rdfs:label \"Sweet cherry\"@en , \"Süßkirsche\"@de , \"Cerisier (cerise douce)\"@fr , \"Prunus avium\"@la ;\n    rdfs:comment \"Most varieties need a pollinator; birds share the harvest unless netted.\"@en ;\n    dwc:scientificName \"Prunus avium\" ;\n    perma:growthForm perma:Tree ;\n    perma:typicalWindow [ perma:activity perma:Flowering ; perma:fromMonth 4 ; perma:toMonth 4 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:Harvest ; perma:part perma:Fruit ; perma:fromMonth 6 ; perma:toMonth 7 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:SummerPrune ; perma:fromMonth 7 ; perma:toMonth 8 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ;\n    perma:seedSaving [ perma:propagation perma:ByGrafting ; perma:lifeCycle perma:Perennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other sweet cherries (most need a compatible pollinator)\" ; perma:selfSows false ;\n        rdfs:comment \"Graft onto Colt or Gisela; pruned in summer after the harvest.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 10 ] , [ perma:method perma:Bottled ; perma:storageMonths 12 ] , [ perma:method perma:Macerated ; perma:storageMonths 24 ] ] .\n\nid:crop-sour-cherry a perma:Crop ;\n    rdfs:label \"Sour cherry\"@en , \"Sauerkirsche\"@de , \"Cerisier acide (griotte)\"@fr , \"Prunus cerasus\"@la ;\n    rdfs:comment \"Morello type; self-fertile, fruits on last year's wood, tolerates a north wall.\"@en ;\n    dwc:scientificName \"Prunus cerasus\" ;\n    perma:growthForm perma:Tree ;\n    perma:typicalWindow [ perma:activity perma:Flowering ; perma:fromMonth 4 ; perma:toMonth 5 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:Harvest ; perma:part perma:Fruit ; perma:fromMonth 7 ; perma:toMonth 8 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ,\n        [ perma:activity perma:SummerPrune ; perma:fromMonth 8 ; perma:toMonth 8 ; perma:confirmation perma:ToConfirm ; perma:basis \"general practice, temperate lowland (north-west Europe), approximate\" ] ;\n    perma:seedSaving [ perma:propagation perma:ByGrafting ; perma:lifeCycle perma:Perennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other sour and sweet cherries\" ; perma:selfSows false ;\n        rdfs:comment \"Self-fertile; graft onto Colt or Gisela, or keep own-root suckers.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 10 ] , [ perma:method perma:Bottled ; perma:storageMonths 12 ] , [ perma:method perma:Macerated ; perma:storageMonths 24 ] ] .\n\n# Added 2026-10-10: crops of the carrot burger, a legume and a companion flower for mixed planting.\n\nid:crop-carrot a perma:Crop ;\n    rdfs:label \"Carrot\"@en , \"Möhre\"@de , \"Carotte\"@fr , \"Daucus carota\"@la ;\n    rdfs:comment \"Sown in place, never transplanted; slow to come up.\"@en ;\n    dwc:scientificName \"Daucus carota\" ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 3 ; perma:germinationDays 14 ; perma:waterMmPerWeek 25.0 ;\n    perma:sowMinTempC 7.0 ; perma:frostTender false ; perma:daysToHarvest 75 ; perma:spacingCm 5 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Biennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"every Daucus carota, wild carrot included\" ; perma:isolationM 800.0 ; perma:seedViabilityYears 3 ; perma:selfSows false ;\n        rdfs:comment \"Keep the best roots over winter and replant them; seed ripens in the second summer.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Root ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Cellar ; perma:storageMonths 5 ] ] .\n\nid:crop-cucumber a perma:Crop ;\n    rdfs:label \"Cucumber\"@en , \"Gurke\"@de , \"Concombre\"@fr , \"Cucumis sativus\"@la ;\n    rdfs:comment \"Gherkins (cornichons) are the same species, picked small. Trails, or climbs a net.\"@en ;\n    dwc:scientificName \"Cucumis sativus\" ;\n    perma:sowingDepthMm 20 ; perma:seedsPerPoint 2 ; perma:germinationDays 7 ; perma:waterMmPerWeek 35.0 ;\n    perma:sowMinTempC 15.0 ; perma:plantOutMinNightC 10.0 ; perma:frostTender true ; perma:daysToHarvest 60 ; perma:spacingCm 40 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"every Cucumis sativus\" ; perma:isolationM 400.0 ; perma:seedViabilityYears 6 ; perma:selfSows false ;\n        rdfs:comment \"Leave a fruit to ripen yellow on the plant; ferment the seed pulp a few days, wash, dry.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Pickled ; perma:storageMonths 12 ] ] .\n\nid:crop-bush-bean a perma:Crop ;\n    rdfs:label \"Bush bean\"@en , \"Buschbohne\"@de , \"Haricot nain\"@fr , \"Phaseolus vulgaris\"@la ;\n    rdfs:comment \"A legume: bacteria on its roots bring nitrogen into the soil. Cut it off at the base when it is done and leave the roots in.\"@en ;\n    dwc:scientificName \"Phaseolus vulgaris\" ;\n    perma:sowingDepthMm 30 ; perma:seedsPerPoint 2 ; perma:germinationDays 8 ; perma:waterMmPerWeek 25.0 ;\n    perma:sowMinTempC 12.0 ; perma:plantOutMinNightC 8.0 ; perma:frostTender true ; perma:daysToHarvest 60 ; perma:spacingCm 15 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:SelfPollinating ;\n        perma:crossesWith \"other Phaseolus vulgaris, rarely\" ; perma:isolationM 5.0 ; perma:seedViabilityYears 3 ; perma:selfSows false ;\n        rdfs:comment \"Let some pods dry on the plant; shell and dry the beans well.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Fruit ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Frozen ; perma:storageMonths 10 ] ] .\n\nid:crop-marigold a perma:Crop ;\n    rdfs:label \"French marigold\"@en , \"Studentenblume\"@de , \"Œillet d'Inde\"@fr , \"Tagetes patula\"@la ;\n    rdfs:comment \"A companion flower, grown for what it does for its neighbours; the petals are edible. GBIF's backbone treats Tagetes patula as a synonym of Tagetes erecta, so the taxon link is to that name.\"@en ;\n    dwc:scientificName \"Tagetes erecta\" ;\n    perma:sowingDepthMm 5 ; perma:seedsPerPoint 2 ; perma:germinationDays 7 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 12.0 ; perma:plantOutMinNightC 8.0 ; perma:frostTender true ; perma:daysToHarvest 60 ; perma:spacingCm 20 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other Tagetes patula\" ; perma:isolationM 200.0 ; perma:seedViabilityYears 3 ; perma:selfSows false ;\n        rdfs:comment \"Dry the spent flower heads; the seeds are the black slivers inside.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Flower ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] , [ perma:method perma:Dried ; perma:storageMonths 12 ] ] .\n\n# Added 2026-10-10: cover crops, for the soil between and after the crops.\n\nid:crop-white-clover a perma:Crop ;\n    rdfs:label \"White clover\"@en , \"Weißklee\"@de , \"Trèfle blanc\"@fr , \"Trifolium repens\"@la ;\n    rdfs:comment \"A low, creeping legume: a living mulch under and between the crops. Cut it and leave it lying.\"@en ;\n    dwc:scientificName \"Trifolium repens\" ; perma:coverCrop true ;\n    perma:sowingDepthMm 5 ; perma:seedsPerPoint 6 ; perma:germinationDays 8 ; perma:waterMmPerWeek 20.0 ;\n    perma:sowMinTempC 8.0 ; perma:frostTender false ; perma:daysToHarvest 60 ; perma:spacingCm 10 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Perennial ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other Trifolium repens\" ; perma:isolationM 200.0 ; perma:seedViabilityYears 3 ; perma:selfSows true ;\n        rdfs:comment \"Spreads by runners; seed is rarely needed twice.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Leaf ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] ] .\n\nid:crop-phacelia a perma:Crop ;\n    rdfs:label \"Phacelia\"@en , \"Phacelia\"@de , \"Phacélie\"@fr , \"Phacelia tanacetifolia\"@la ;\n    rdfs:comment \"Quick cover that belongs to no vegetable family, so it fits any rotation; bees love it. Frost kills it and leaves a mulch.\"@en ;\n    dwc:scientificName \"Phacelia tanacetifolia\" ; perma:coverCrop true ;\n    perma:sowingDepthMm 10 ; perma:seedsPerPoint 4 ; perma:germinationDays 10 ; perma:waterMmPerWeek 15.0 ;\n    perma:sowMinTempC 8.0 ; perma:frostTender true ; perma:daysToHarvest 50 ; perma:spacingCm 10 ;\n    perma:seedSaving [ perma:propagation perma:FromSeed ; perma:lifeCycle perma:Annual ; perma:pollination perma:InsectPollinated ;\n        perma:crossesWith \"other Phacelia tanacetifolia\" ; perma:isolationM 200.0 ; perma:seedViabilityYears 4 ; perma:selfSows true ;\n        rdfs:comment \"Cut before the seed ripens, or it sows itself everywhere.\"@en ;\n        perma:confirmation perma:ToConfirm ; perma:basis \"general growing and seed-saving guidance, approximate\" ] ;\n    perma:yields [ perma:part perma:Flower ; perma:keeps [ perma:method perma:Fresh ; perma:storageMonths 0 ] ] .\n\nid:crop-white-mustard perma:coverCrop true .\n\n# ------------------------------------------------------------ what each crop takes from the bed and gives to it\n#\n# For planting mixed (tbox/perma-food.ttl; packages/core/src/planting.ts places the plants from these).\n# Traditional companion-planting guidance: evidence for single pairings is mixed, and all of it is to\n# confirm on the bed itself. Neighbours are stated once and hold both ways. Trees are not in this list.\nid:crop-courgette dwc:family \"Cucurbitaceae\" ; perma:feeding perma:HeavyFeeder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 60 ;\n    perma:gives perma:CoversSoil ;\n    perma:goodNeighbour id:crop-bush-bean , id:crop-marigold , id:crop-onion .\nid:crop-onion dwc:family \"Amaryllidaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 40 ;\n    perma:gives perma:ConfusesPests ;\n    perma:goodNeighbour id:crop-carrot , id:crop-lettuce , id:crop-tomato , id:crop-swiss-chard , id:crop-sweet-pepper , id:crop-white-cabbage ;\n    perma:badNeighbour id:crop-bush-bean .\nid:crop-sweet-pepper dwc:family \"Solanaceae\" ; perma:feeding perma:HeavyFeeder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 70 ;\n    perma:goodNeighbour id:crop-basil , id:crop-carrot , id:crop-marigold .\nid:crop-dill dwc:family \"Apiaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 90 ;\n    perma:gives perma:FeedsPollinators ;\n    perma:goodNeighbour id:crop-white-cabbage , id:crop-cucumber , id:crop-lettuce ;\n    perma:badNeighbour id:crop-carrot , id:crop-caraway .\nid:crop-white-mustard dwc:family \"Brassicaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:DeepRoot ; perma:heightCm 60 ;\n    perma:gives perma:CoversSoil , perma:LoosensSoil .\nid:crop-tomato dwc:family \"Solanaceae\" ; perma:feeding perma:HeavyFeeder ; perma:rootDepth perma:DeepRoot ; perma:heightCm 150 ;\n    perma:goodNeighbour id:crop-basil , id:crop-carrot , id:crop-garlic , id:crop-parsley , id:crop-chives , id:crop-marigold , id:crop-lettuce ;\n    perma:badNeighbour id:crop-white-cabbage .\nid:crop-aubergine dwc:family \"Solanaceae\" ; perma:feeding perma:HeavyFeeder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 80 ;\n    perma:goodNeighbour id:crop-bush-bean , id:crop-basil , id:crop-thyme .\nid:crop-garlic dwc:family \"Amaryllidaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 50 ;\n    perma:gives perma:ConfusesPests ;\n    perma:goodNeighbour id:crop-carrot , id:crop-lettuce , id:crop-swiss-chard ;\n    perma:badNeighbour id:crop-bush-bean .\nid:crop-basil dwc:family \"Lamiaceae\" ; perma:feeding perma:MediumFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 40 ;\n    perma:gives perma:ConfusesPests , perma:FeedsPollinators .\nid:crop-thyme dwc:family \"Lamiaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 25 ;\n    perma:gives perma:ConfusesPests , perma:FeedsPollinators , perma:CoversSoil ;\n    perma:goodNeighbour id:crop-white-cabbage , id:crop-tomato .\nid:crop-rosemary dwc:family \"Lamiaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:DeepRoot ; perma:heightCm 100 ;\n    perma:gives perma:ConfusesPests , perma:FeedsPollinators ;\n    perma:goodNeighbour id:crop-carrot , id:crop-white-cabbage , id:crop-bush-bean .\nid:crop-white-cabbage dwc:family \"Brassicaceae\" ; perma:feeding perma:HeavyFeeder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 40 ;\n    perma:goodNeighbour id:crop-swiss-chard , id:crop-marigold , id:crop-spinach .\nid:crop-caraway dwc:family \"Apiaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:DeepRoot ; perma:heightCm 60 ;\n    perma:gives perma:LoosensSoil , perma:FeedsPollinators .\nid:crop-lettuce dwc:family \"Asteraceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 25 ;\n    perma:goodNeighbour id:crop-carrot , id:crop-radish , id:crop-chives , id:crop-spring-onion , id:crop-cucumber , id:crop-bush-bean , id:crop-rocket , id:crop-spinach ;\n    perma:badNeighbour id:crop-parsley .\nid:crop-rocket dwc:family \"Brassicaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 25 ;\n    perma:goodNeighbour id:crop-bush-bean .\nid:crop-radish dwc:family \"Brassicaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 15 ;\n    perma:gives perma:LoosensSoil ;\n    perma:goodNeighbour id:crop-carrot , id:crop-cucumber , id:crop-spinach , id:crop-bush-bean .\nid:crop-spinach dwc:family \"Amaranthaceae\" ; perma:feeding perma:MediumFeeder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 25 ;\n    perma:goodNeighbour id:crop-bush-bean .\nid:crop-swiss-chard dwc:family \"Amaranthaceae\" ; perma:feeding perma:MediumFeeder ; perma:rootDepth perma:DeepRoot ; perma:heightCm 50 ;\n    perma:goodNeighbour id:crop-bush-bean .\nid:crop-spring-onion dwc:family \"Amaryllidaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 35 ;\n    perma:gives perma:ConfusesPests ;\n    perma:goodNeighbour id:crop-carrot ;\n    perma:badNeighbour id:crop-bush-bean .\nid:crop-chives dwc:family \"Amaryllidaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 30 ;\n    perma:gives perma:ConfusesPests , perma:FeedsPollinators ;\n    perma:goodNeighbour id:crop-carrot , id:crop-parsley ;\n    perma:badNeighbour id:crop-bush-bean .\nid:crop-parsley dwc:family \"Apiaceae\" ; perma:feeding perma:MediumFeeder ; perma:rootDepth perma:DeepRoot ; perma:heightCm 30 ;\n    perma:gives perma:FeedsPollinators ;\n    perma:goodNeighbour id:crop-radish .\nid:crop-carrot dwc:family \"Apiaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:DeepRoot ; perma:heightCm 30 ;\n    perma:gives perma:LoosensSoil .\nid:crop-cucumber dwc:family \"Cucurbitaceae\" ; perma:feeding perma:HeavyFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 40 ;\n    perma:gives perma:CoversSoil ;\n    perma:goodNeighbour id:crop-bush-bean , id:crop-marigold .\nid:crop-bush-bean dwc:family \"Fabaceae\" ; perma:feeding perma:SoilBuilder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 45 ;\n    perma:gives perma:FixesNitrogen .\nid:crop-marigold dwc:family \"Asteraceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 30 ;\n    perma:gives perma:ConfusesPests , perma:FeedsPollinators .\nid:crop-white-clover dwc:family \"Fabaceae\" ; perma:feeding perma:SoilBuilder ; perma:rootDepth perma:ShallowRoot ; perma:heightCm 15 ;\n    perma:gives perma:FixesNitrogen , perma:CoversSoil , perma:FeedsPollinators .\nid:crop-phacelia dwc:family \"Hydrophyllaceae\" ; perma:feeding perma:LightFeeder ; perma:rootDepth perma:MediumRoot ; perma:heightCm 60 ;\n    perma:gives perma:CoversSoil , perma:FeedsPollinators , perma:LoosensSoil .\n";
export const SHAPES = "@prefix app:    <https://permtek-5.digitalhome.cloud/ontology#> .\n@prefix appsh:  <https://permtek-5.digitalhome.cloud/shapes#> .\n@prefix sh:     <http://www.w3.org/ns/shacl#> .\n@prefix skos:   <http://www.w3.org/2004/02/skos/core#> .\n@prefix schema: <https://schema.org/> .\n\n# ============================================================\n# SHACL shapes, v0.1: what an A-Box must satisfy. Validate an A-Box\n# TOGETHER with tbox/app-concepts.ttl, so a type can be checked against its\n# scheme. The cloud refuses an A-Box that does not conform (ADR-0007).\n# ============================================================\n\nappsh:InThingTypes a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue app:ThingTypes ] .\n\nappsh:ThingShape a sh:NodeShape ;\n    sh:targetClass app:Thing ;\n    sh:property [\n        sh:path schema:name ;\n        sh:minCount 1 ;\n        sh:message \"A thing needs a name.\"@en ;\n    ] ;\n    sh:property [\n        sh:path app:thingType ;\n        sh:maxCount 1 ;\n        sh:node appsh:InThingTypes ;\n        sh:message \"A thing's type is one concept from app:ThingTypes.\"@en ;\n    ] ;\n    sh:property [\n        sh:path app:locatedIn ;\n        sh:class app:Place ;\n        sh:message \"A thing is located in a place.\"@en ;\n    ] .\n\nappsh:PlaceShape a sh:NodeShape ;\n    sh:targetClass app:Place ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"A place needs a name.\"@en ] .\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix permash: <https://permaculture.digitalhome.cloud/shapes#> .\n@prefix sh:      <http://www.w3.org/ns/shacl#> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix geo:     <http://www.opengis.net/ont/geosparql#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n\n# ============================================================\n# SHACL shapes for the vegetation map, v0.1. Validate an A-Box TOGETHER\n# with tbox/perma-vegetation-concepts.ttl, so each class and status can be\n# checked against its scheme. Nothing reaches the map, the nest or the twin\n# unless it conforms (design rule 5).\n# ============================================================\n\npermash:InVegetationClasses a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue perma:VegetationClasses ] .\npermash:InVegetationStatuses a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue perma:VegetationStatuses ] .\npermash:InMapStatuses a sh:NodeShape ;\n    sh:property [ sh:path skos:inScheme ; sh:hasValue perma:MapStatuses ] .\n\npermash:VegetationUnitShape a sh:NodeShape ;\n    sh:targetClass perma:VegetationUnit , perma:VegetationPatch , perma:Plant ;\n    sh:property [\n        sh:path perma:vegetationClass ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InVegetationClasses ;\n        sh:message \"A vegetation unit has exactly one class from perma:VegetationClasses.\"@en ;\n    ] ;\n    sh:property [\n        sh:path perma:vegetationStatus ; sh:maxCount 1 ; sh:node permash:InVegetationStatuses ;\n        sh:message \"A vegetation status is one concept from perma:VegetationStatuses.\"@en ;\n    ] ;\n    sh:property [\n        sh:path perma:mapStatus ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InMapStatuses ;\n        sh:message \"Every unit on the map says how sure it is: one concept from perma:MapStatuses.\"@en ;\n    ] ;\n    sh:property [\n        sh:path geo:hasGeometry ; sh:minCount 1 ; sh:maxCount 1 ;\n        sh:message \"A vegetation unit has one geometry.\"@en ;\n    ] ;\n    sh:property [\n        sh:path perma:heightM ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ; sh:maxInclusive 60 ;\n        sh:message \"Height is one number of metres between 0 and 60.\"@en ;\n    ] ;\n    sh:property [\n        sh:path perma:canopyRadiusM ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ;\n        sh:message \"Canopy radius is one number of metres.\"@en ;\n    ] ;\n    sh:property [\n        sh:path perma:hasCanopy ; sh:maxCount 1 ; sh:datatype xsd:boolean ;\n    ] ;\n    sh:property [\n        sh:path rdfs:label ; sh:minCount 1 ;\n        sh:message \"A vegetation unit needs a label a person can read.\"@en ;\n    ] .\n\npermash:GeometryShape a sh:NodeShape ;\n    sh:targetObjectsOf geo:hasGeometry ;\n    sh:property [\n        sh:path geo:asWKT ; sh:minCount 1 ; sh:maxCount 1 ;\n        sh:message \"A geometry is given as one WKT literal (local site frame, metres).\"@en ;\n    ] .\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix permash: <https://permaculture.digitalhome.cloud/shapes#> .\n@prefix sh:      <http://www.w3.org/ns/shacl#> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix schema:  <https://schema.org/> .\n@prefix dwc:     <http://rs.tdwg.org/dwc/terms/> .\n\n# ============================================================\n# SHACL shapes for crops, site calendars and recipes, v0.1. Validate\n# TOGETHER with tbox/perma-food-concepts.ttl and tbox/perma-vegetation-concepts.ttl\n# (for the confirmation statuses), and with the crop library when checking a\n# calendar or a recipe.\n# ============================================================\n\npermash:InPlantParts a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:PlantParts ] .\npermash:InGardenActivities a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:GardenActivities ] .\npermash:InMapStatusesFood a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:MapStatuses ] .\n\npermash:CropShape a sh:NodeShape ;\n    sh:targetClass perma:Crop ;\n    sh:property [ sh:path rdfs:label ; sh:qualifiedValueShape [ sh:languageIn ( \"en\" ) ] ; sh:qualifiedMinCount 1 ;\n                  sh:message \"A crop needs an English name.\"@en ] ;\n    sh:property [ sh:path rdfs:label ; sh:qualifiedValueShape [ sh:languageIn ( \"fr\" ) ] ; sh:qualifiedMinCount 1 ;\n                  sh:message \"A crop needs a French name.\"@en ] ;\n    sh:property [ sh:path rdfs:label ; sh:qualifiedValueShape [ sh:languageIn ( \"de\" ) ] ; sh:qualifiedMinCount 1 ;\n                  sh:message \"A crop needs a German name.\"@en ] ;\n    sh:property [ sh:path rdfs:label ; sh:qualifiedValueShape [ sh:languageIn ( \"la\" ) ] ; sh:qualifiedMinCount 1 ;\n                  sh:message \"A crop needs its Latin name (rdfs:label @la).\"@en ] ;\n    sh:property [ sh:path perma:taxon ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;\n                  sh:pattern \"^https://www\\\\.gbif\\\\.org/species/[0-9]+$\" ;\n                  sh:message \"A crop links at most one GBIF taxon (https://www.gbif.org/species/KEY).\"@en ] ;\n    sh:property [ sh:path dwc:scientificName ; sh:minCount 1 ; sh:maxCount 1 ;\n                  sh:message \"A crop names its taxon (dwc:scientificName) until perma-bio links the IRI.\"@en ] ;\n    sh:property [ sh:path perma:yields ; sh:minCount 1 ; sh:node permash:HarvestPartShape ;\n                  sh:message \"A crop yields at least one harvested part.\"@en ] ;\n    sh:property [ sh:path perma:sowMinTempC ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive -5 ; sh:maxInclusive 35 ] ;\n    sh:property [ sh:path perma:plantOutMinNightC ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive -5 ; sh:maxInclusive 25 ] ;\n    sh:property [ sh:path perma:boltAboveC ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 5 ; sh:maxInclusive 45 ] ;\n    sh:property [ sh:path perma:frostTender ; sh:maxCount 1 ; sh:datatype xsd:boolean ] ;\n    sh:property [ sh:path perma:daysToHarvest ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:maxInclusive 730 ] ;\n    sh:property [ sh:path perma:spacingCm ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:maxInclusive 2000 ] ;\n    sh:property [ sh:path perma:sowingDepthMm ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ; sh:maxInclusive 150 ] ;\n    sh:property [ sh:path perma:seedsPerPoint ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:maxInclusive 20 ] ;\n    sh:property [ sh:path perma:germinationDays ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:maxInclusive 120 ] ;\n    sh:property [ sh:path perma:waterMmPerWeek ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ; sh:maxInclusive 100 ] ;\n    sh:property [ sh:path perma:growthForm ; sh:maxCount 1 ; sh:in ( perma:Tree perma:Shrub ) ;\n                  sh:message \"A crop's growth form is perma:Tree or perma:Shrub (or none, for herbaceous crops).\"@en ] ;\n    sh:property [ sh:path perma:typicalWindow ; sh:node permash:TypicalWindowShape ] ;\n    sh:property [ sh:path perma:feeding ; sh:maxCount 1 ; sh:node permash:InFeedingLevels ;\n                  sh:message \"A crop's feeding is one of perma:FeedingLevels.\"@en ] ;\n    sh:property [ sh:path perma:rootDepth ; sh:maxCount 1 ; sh:node permash:InRootDepths ;\n                  sh:message \"A crop's root depth is one of perma:RootDepths.\"@en ] ;\n    sh:property [ sh:path perma:heightCm ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:maxInclusive 4000 ] ;\n    sh:property [ sh:path perma:gives ; sh:node permash:InSoilGifts ; sh:message \"What a crop gives is from perma:SoilGifts.\"@en ] ;\n    sh:property [ sh:path dwc:family ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path perma:coverCrop ; sh:maxCount 1 ; sh:datatype xsd:boolean ] ;\n    sh:property [ sh:path perma:goodNeighbour ; sh:class perma:Crop ] ;\n    sh:property [ sh:path perma:badNeighbour ; sh:class perma:Crop ] .\n\npermash:InFeedingLevels a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:FeedingLevels ] .\npermash:InRootDepths a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:RootDepths ] .\npermash:InSoilGifts a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:SoilGifts ] .\n\npermash:TypicalWindowShape a sh:NodeShape ;\n    sh:property [ sh:path perma:activity ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InGardenActivities ;\n                  sh:message \"A typical window is for one activity from perma:GardenActivities.\"@en ] ;\n    sh:property [ sh:path perma:part ; sh:maxCount 1 ; sh:node permash:InPlantParts ] ;\n    sh:property [ sh:path perma:fromMonth ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 12 ; sh:message \"fromMonth is 1..12.\"@en ] ;\n    sh:property [ sh:path perma:toMonth ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 12 ; sh:message \"toMonth is 1..12.\"@en ] ;\n    sh:property [ sh:path perma:confirmation ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InMapStatusesFood ] ;\n    sh:property [ sh:path perma:basis ; sh:minCount 1 ; sh:message \"Say for which climate the window is typical (perma:basis).\"@en ] .\n\npermash:HarvestPartShape a sh:NodeShape ;\n    sh:property [ sh:path perma:part ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InPlantParts ;\n                  sh:message \"A harvested part is one concept from perma:PlantParts.\"@en ] ;\n    sh:property [ sh:path perma:keeps ; sh:minCount 1 ; sh:node permash:KeepingWayShape ;\n                  sh:message \"Say at least one way the part keeps (fresh counts).\"@en ] .\n\npermash:InPreservationMethods a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:PreservationMethods ] .\n\npermash:KeepingWayShape a sh:NodeShape ;\n    sh:property [ sh:path perma:method ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InPreservationMethods ;\n                  sh:message \"A way of keeping is one concept from perma:PreservationMethods.\"@en ] ;\n    sh:property [ sh:path perma:storageMonths ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 0 ; sh:maxInclusive 36 ; sh:message \"Months it keeps this way, 0..36.\"@en ] .\n\npermash:SeasonWindowShape a sh:NodeShape ;\n    sh:targetClass perma:SeasonWindow ;\n    sh:property [ sh:path perma:forCrop ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:Crop ;\n                  sh:message \"A season window is for one crop of the library.\"@en ] ;\n    sh:property [ sh:path perma:atSite ; sh:minCount 1 ; sh:maxCount 1 ;\n                  sh:message \"A season window holds for one site.\"@en ] ;\n    sh:property [ sh:path perma:activity ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InGardenActivities ;\n                  sh:message \"A season window is for one activity from perma:GardenActivities.\"@en ] ;\n    sh:property [ sh:path perma:fromMonth ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 12 ; sh:message \"fromMonth is 1..12.\"@en ] ;\n    sh:property [ sh:path perma:toMonth ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 12 ; sh:message \"toMonth is 1..12.\"@en ] ;\n    sh:property [ sh:path perma:confirmation ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InMapStatusesFood ;\n                  sh:message \"Say how sure the window is: one concept from perma:MapStatuses.\"@en ] .\n\npermash:RecipeShape a sh:NodeShape ;\n    sh:targetClass schema:Recipe ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:message \"A recipe needs a name.\"@en ] ;\n    sh:property [ sh:path perma:usesIngredient ; sh:minCount 1 ; sh:node permash:IngredientUseShape ;\n                  sh:message \"A recipe lists its ingredients as perma:IngredientUse.\"@en ] ;\n    sh:property [ sh:path perma:preservesAs ; sh:maxCount 1 ; sh:node permash:InPreservationMethods ] ;\n    sh:property [ sh:path perma:shelfLifeDays ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ] .\n\npermash:IngredientUseShape a sh:NodeShape ;\n    sh:property [ sh:path schema:name ; sh:minCount 1 ; sh:maxCount 1 ;\n                  sh:message \"An ingredient keeps its line as written (schema:name).\"@en ] ;\n    sh:property [ sh:path perma:crop ; sh:maxCount 1 ; sh:class perma:Crop ] ;\n    sh:property [ sh:path perma:part ; sh:maxCount 1 ; sh:node permash:InPlantParts ] ;\n    sh:property [ sh:path perma:acceptsMethod ; sh:node permash:InPreservationMethods ;\n                  sh:message \"An ingredient accepts methods from perma:PreservationMethods.\"@en ] .\n\npermash:CropNeedsPart a sh:NodeShape ;\n    sh:targetSubjectsOf perma:crop ;\n    sh:property [ sh:path perma:part ; sh:minCount 1 ;\n                  sh:message \"An ingredient from a crop says which part of it.\"@en ] .\n\npermash:InLifeCycles a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:LifeCycles ] .\npermash:InPollinationTypes a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:PollinationTypes ] .\npermash:InPropagationMethods a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:PropagationMethods ] .\n\n# Grown from seed: then say how it is pollinated and how long the seed stays good.\npermash:SeedPropagatedShape a sh:NodeShape ;\n    sh:targetSubjectsOf perma:propagation ;\n    sh:or ( [ sh:not [ sh:property [ sh:path perma:propagation ; sh:hasValue perma:FromSeed ] ] ]\n            [ sh:property [ sh:path perma:pollination ; sh:minCount 1 ] ;\n              sh:property [ sh:path perma:seedViabilityYears ; sh:minCount 1 ] ] ) ;\n    sh:message \"A crop kept from seed says how it is pollinated and how long the seed stays good.\"@en .\n\npermash:SeedSavingShape a sh:NodeShape ;\n    sh:targetObjectsOf perma:seedSaving ;\n    sh:property [ sh:path perma:lifeCycle ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InLifeCycles ;\n                  sh:message \"Seed saving says the life cycle (perma:LifeCycles).\"@en ] ;\n    sh:property [ sh:path perma:propagation ; sh:minCount 1 ; sh:node permash:InPropagationMethods ;\n                  sh:message \"Say how the crop is propagated (perma:PropagationMethods).\"@en ] ;\n    sh:property [ sh:path perma:pollination ; sh:maxCount 1 ; sh:node permash:InPollinationTypes ] ;\n    sh:property [ sh:path perma:isolationM ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ] ;\n    sh:property [ sh:path perma:seedViabilityYears ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 0 ; sh:maxInclusive 30 ] ;\n    sh:property [ sh:path perma:confirmation ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InMapStatusesFood ] .\n\npermash:TaxonLinkShape a sh:NodeShape ;\n    sh:targetSubjectsOf perma:taxrefId ;\n    sh:property [ sh:path perma:taxrefId ; sh:maxCount 1 ; sh:pattern \"^[0-9]+$\" ;\n                  sh:message \"A taxon has at most one TAXREF ID (CD_NOM, digits).\"@en ] .\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix permash: <https://permaculture.digitalhome.cloud/shapes#> .\n@prefix sh:      <http://www.w3.org/ns/shacl#> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n\n# ============================================================\n# SHACL shapes for a habitat's A-Box, v0.1. Validate TOGETHER with\n# tbox/perma-habitat-concepts.ttl. The cloud checks every save with them\n# (ADR-0007), without the crop library: crops are checked by IRI. What SHACL\n# core cannot say (a cell inside its bed) packages/core checks before saving.\n# ============================================================\n\npermash:InZoneKinds a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:ZoneKinds ] .\npermash:InExposures a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:Exposures ] .\npermash:InCellStatuses a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:CellStatuses ] .\npermash:InPeriodKinds a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:PeriodKinds ] .\npermash:InGuildTypes a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:GuildTypes ] .\npermash:InRobotModels a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:RobotModels ] .\npermash:InSubstrateKinds a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:SubstrateKinds ] .\npermash:InSurfaceCategories a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:SurfaceCategories ] .\npermash:InWaterStoreKinds a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:WaterStoreKinds ] .\npermash:InWaterKinds a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:WaterKinds ] .\npermash:InValveKinds a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:ValveKinds ] .\n\npermash:LibraryCrop a sh:PropertyShape ;\n    sh:path perma:grows ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;\n    sh:pattern \"^https://permaculture\\\\.digitalhome\\\\.cloud/id/crop-[a-z0-9-]+$\" ;\n    sh:message \"It grows one crop of the library (…/id/crop-…).\"@en .\n\npermash:GardenZoneShape a sh:NodeShape ;\n    sh:targetClass perma:GardenZone ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"An area needs a name.\"@en ] ;\n    sh:property [ sh:path perma:zoneKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InZoneKinds ;\n                  sh:message \"An area is of one kind from perma:ZoneKinds.\"@en ] ;\n    sh:property [ sh:path perma:exposure ; sh:node permash:InExposures ;\n                  sh:message \"Exposures come from perma:Exposures.\"@en ] ;\n    sh:property [ sh:path perma:areaM2 ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ;\n                  sh:message \"Area in m², at least 0.\"@en ] ;\n    sh:property [ sh:path perma:microclimateOffsetC ; sh:maxCount 1 ; sh:datatype xsd:decimal ;\n                  sh:minInclusive -5 ; sh:maxInclusive 5 ; sh:message \"The microclimate offset is -5..5 °C.\"@en ] .\n\npermash:GuildShape a sh:NodeShape ;\n    sh:targetClass perma:Guild ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A Perma5Guild needs a name.\"@en ] ;\n    sh:property [ sh:path perma:inZone ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:GardenZone ;\n                  sh:message \"A Perma5Guild stands in one area of the site.\"@en ] ;\n    sh:property [ sh:path perma:guildType ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InGuildTypes ;\n                  sh:message \"A Perma5Guild is of one type from perma:GuildTypes.\"@en ] ;\n    sh:property [ sh:path perma:robotModel ; sh:maxCount 1 ; sh:node permash:InRobotModels ;\n                  sh:message \"A guild's robot is one concept from perma:RobotModels.\"@en ] ;\n    sh:property [ sh:path perma:wormsMayLeave ; sh:maxCount 1 ; sh:datatype xsd:boolean ] .\n\npermash:GrowingBedShape a sh:NodeShape ;\n    sh:targetClass perma:GrowingBed ;\n    sh:property [ sh:path perma:inGuild ; sh:maxCount 1 ; sh:class perma:Guild ;\n                  sh:message \"A bed belongs to at most one Perma5Guild of the site.\"@en ] ;\n    sh:property [ sh:path perma:inFarm ; sh:maxCount 1 ; sh:class perma:BedFarm ;\n                  sh:message \"A bed belongs to at most one farm of beds of the site.\"@en ] ;\n    sh:property [ sh:path perma:surfaceCategory ; sh:maxCount 1 ; sh:node permash:InSurfaceCategories ;\n                  sh:message \"A bed's surface category is one concept from perma:SurfaceCategories.\"@en ] ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A bed needs a name.\"@en ] ;\n    sh:property [ sh:path perma:inZone ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:GardenZone ;\n                  sh:message \"A bed lies in one area of the site.\"@en ] ;\n    sh:property [ sh:path perma:lengthCm ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 10 ; sh:maxInclusive 3000 ; sh:message \"A bed's length is 10..3000 cm.\"@en ] ;\n    sh:property [ sh:path perma:widthCm ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 10 ; sh:maxInclusive 1000 ; sh:message \"A bed's width is 10..1000 cm.\"@en ] ;\n    sh:property [ sh:path perma:substrateDepthCm ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 0 ; sh:maxInclusive 300 ; sh:message \"Substrate depth is 0..300 cm.\"@en ] ;\n    sh:property [ sh:path perma:cellSizeCm ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 5 ; sh:maxInclusive 100 ; sh:message \"A bed's cells are 5..100 cm.\"@en ] ;\n    sh:property [ sh:path perma:substrateKind ; sh:maxCount 1 ; sh:node permash:InSubstrateKinds ;\n                  sh:message \"A bed's substrate is one concept from perma:SubstrateKinds.\"@en ] ;\n    sh:property [ sh:path perma:tankPipeCount ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 0 ; sh:maxInclusive 20 ; sh:message \"A bed has 0..20 tank pipes.\"@en ] ;\n    sh:property [ sh:path perma:tankPipeMm ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 50 ; sh:maxInclusive 200 ; sh:message \"Tank pipes are 50..200 mm across.\"@en ] ;\n    sh:property [ sh:path perma:mulchCm ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ; sh:maxInclusive 15 ;\n                  sh:message \"Mulch is 0..15 cm thick.\"@en ] ;\n    sh:property [ sh:path perma:wormBinCm ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ;\n                  sh:lessThan perma:lengthCm ;\n                  sh:message \"The worm box is shorter than its bed.\"@en ] .\n\n# A farm of beds (docs/adr/0027): its beds share one size; up to 50 of them, with paths of 20..200 cm.\npermash:BedFarmShape a sh:NodeShape ;\n    sh:targetClass perma:BedFarm ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A farm of beds needs a name.\"@en ] ;\n    sh:property [ sh:path perma:inZone ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:GardenZone ;\n                  sh:message \"A farm of beds lies in one area of the site.\"@en ] ;\n    sh:property [ sh:path perma:bedRows ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 10 ; sh:message \"A farm has 1..10 rows of beds.\"@en ] ;\n    sh:property [ sh:path perma:bedsPerRow ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 10 ; sh:message \"A farm has 1..10 beds per row.\"@en ] ;\n    sh:property [ sh:path perma:pathCm ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 20 ; sh:maxInclusive 200 ; sh:message \"Paths between beds are 20..200 cm.\"@en ] ;\n    sh:property [ sh:path perma:bedLengthCm ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 10 ; sh:maxInclusive 3000 ; sh:message \"A bed's length is 10..3000 cm.\"@en ] ;\n    sh:property [ sh:path perma:bedWidthCm ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 10 ; sh:maxInclusive 1000 ; sh:message \"A bed's width is 10..1000 cm.\"@en ] ;\n    sh:property [ sh:path perma:cellSizeCm ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 5 ; sh:maxInclusive 100 ; sh:message \"A bed's cells are 5..100 cm.\"@en ] .\n\n# A plant set in a space's graph (a person's own, or the edge agent's draft): a name, and members with a library crop and a share.\npermash:PlantSetShape a sh:NodeShape ;\n    sh:targetClass perma:PlantSet ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:message \"A plant set needs a name.\"@en ] ;\n    sh:property [ sh:path perma:member ; sh:minCount 1 ; sh:node permash:SetMemberShape ;\n                  sh:message \"A plant set has at least one member.\"@en ] ;\n    sh:property [ sh:path perma:setFor ; sh:node permash:InSurfaceCategories ;\n                  sh:message \"A plant set is for concepts from perma:SurfaceCategories.\"@en ] ;\n    sh:property [ sh:path perma:draft ; sh:maxCount 1 ; sh:datatype xsd:boolean ] .\npermash:SetMemberShape a sh:NodeShape ;\n    sh:property [ sh:path perma:memberCrop ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;\n                  sh:pattern \"^https://permaculture\\\\.digitalhome\\\\.cloud/id/crop-[a-z0-9-]+$\" ;\n                  sh:message \"A member is one crop of the library (…/id/crop-…).\"@en ] ;\n    sh:property [ sh:path perma:share ; sh:minCount 1 ; sh:maxCount 1 ; sh:minExclusive 0 ; sh:maxInclusive 100 ;\n                  sh:message \"A member's share is above 0, up to 100.\"@en ] .\n\n# A bed's growing period (docs/adr/0029). That a bed's periods do not overlap, packages/core checks.\npermash:GrowingPeriodShape a sh:NodeShape ;\n    sh:targetClass perma:GrowingPeriod ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A period needs a name.\"@en ] ;\n    sh:property [ sh:path perma:ofBed ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:GrowingBed ;\n                  sh:message \"A period belongs to one bed of the site.\"@en ] ;\n    sh:property [ sh:path perma:fromMonth ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 12 ; sh:message \"A period starts in a month 1..12.\"@en ] ;\n    sh:property [ sh:path perma:toMonth ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1 ; sh:maxInclusive 12 ; sh:message \"A period ends in a month 1..12.\"@en ] ;\n    sh:property [ sh:path perma:periodKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InPeriodKinds ;\n                  sh:message \"A period's kind is one concept from perma:PeriodKinds.\"@en ] ;\n    sh:property [ sh:path perma:setChoice ; sh:node permash:SetChoiceShape ] .\npermash:SetChoiceShape a sh:NodeShape ;\n    sh:property [ sh:path perma:plantSet ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;\n                  sh:message \"A set choice names one plant set.\"@en ] ;\n    sh:property [ sh:path perma:share ; sh:minCount 1 ; sh:maxCount 1 ; sh:minExclusive 0 ; sh:maxInclusive 100 ;\n                  sh:message \"A set's share is above 0, up to 100.\"@en ] .\n\npermash:PlantingCellShape a sh:NodeShape ;\n    sh:targetClass perma:PlantingCell ;\n    sh:property [ sh:path perma:inBed ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:GrowingBed ;\n                  sh:message \"A cell belongs to one bed of the site.\"@en ] ;\n    sh:property [ sh:path perma:row ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ;\n                  sh:message \"A cell's row is a whole number from 0.\"@en ] ;\n    sh:property [ sh:path perma:col ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ;\n                  sh:message \"A cell's column is a whole number from 0.\"@en ] ;\n    sh:property permash:LibraryCrop ;\n    sh:property [ sh:path perma:cellStatus ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InCellStatuses ;\n                  sh:message \"A cell's status is one concept from perma:CellStatuses.\"@en ] ;\n    sh:property [ sh:path perma:cellSowingDepthMm ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ; sh:maxInclusive 150 ;\n                  sh:message \"Sowing depth is 0..150 mm.\"@en ] ;\n    sh:property [ sh:path perma:cellSeedsPerPoint ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:maxInclusive 20 ;\n                  sh:message \"Seeds per point is 1..20.\"@en ] ;\n    sh:property [ sh:path perma:sownOn ; sh:maxCount 1 ; sh:datatype xsd:date ;\n                  sh:message \"Sown on is a date (YYYY-MM-DD).\"@en ] ;\n    sh:property [ sh:path perma:inPeriod ; sh:maxCount 1 ; sh:class perma:GrowingPeriod ;\n                  sh:message \"A cell is the target of at most one period of the site.\"@en ] .\n\npermash:GardenPlantShape a sh:NodeShape ;\n    sh:targetClass perma:GardenPlant ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A garden plant needs a name.\"@en ] ;\n    sh:property [ sh:path perma:inZone ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:GardenZone ;\n                  sh:message \"A garden plant stands in one area of the site.\"@en ] ;\n    sh:property permash:LibraryCrop ;\n    sh:property [ sh:path perma:plantedYear ; sh:maxCount 1 ; sh:datatype xsd:integer ;\n                  sh:minInclusive 1800 ; sh:maxInclusive 2200 ; sh:message \"Planted in: a year.\"@en ] ;\n    sh:property [ sh:path perma:rootstock ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path perma:xM ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ;\n                  sh:message \"x is metres from the area's edge, at least 0.\"@en ] ;\n    sh:property [ sh:path perma:yM ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ;\n                  sh:message \"y is metres from the area's edge, at least 0.\"@en ] .\n\n# ------------------------------------------------------------ water (v0.2, docs/adr/0025)\n\npermash:RainCatchmentShape a sh:NodeShape ;\n    sh:targetClass perma:RainCatchment ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A rain catchment needs a name.\"@en ] ;\n    sh:property [ sh:path perma:inGuild ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:Guild ;\n                  sh:message \"A rain catchment belongs to one Perma5Guild.\"@en ] ;\n    sh:property [ sh:path perma:inZone ; sh:maxCount 1 ; sh:class perma:GardenZone ] ;\n    sh:property [ sh:path perma:catchmentM2 ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:decimal ;\n                  sh:minExclusive 0 ; sh:maxInclusive 1000 ; sh:message \"A catchment is over 0 and up to 1000 m².\"@en ] ;\n    sh:property [ sh:path perma:runoffShare ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ; sh:maxInclusive 1 ;\n                  sh:message \"The runoff share is 0..1.\"@en ] ;\n    sh:property [ sh:path perma:drainsTo ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:WaterStore ;\n                  sh:message \"A rain catchment fills one water store.\"@en ] .\n\npermash:WaterStoreShape a sh:NodeShape ;\n    sh:targetClass perma:WaterStore ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A water store needs a name.\"@en ] ;\n    sh:property [ sh:path perma:inGuild ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:Guild ;\n                  sh:message \"A water store belongs to one Perma5Guild.\"@en ] ;\n    sh:property [ sh:path perma:inZone ; sh:maxCount 1 ; sh:class perma:GardenZone ;\n                  sh:message \"A water store stands in at most one area (its guild's when none is said).\"@en ] ;\n    sh:property [ sh:path perma:storeKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InWaterStoreKinds ;\n                  sh:message \"A water store is of one kind from perma:WaterStoreKinds.\"@en ] ;\n    sh:property [ sh:path perma:capacityL ; sh:maxCount 1 ; sh:datatype xsd:decimal ; sh:minInclusive 0 ; sh:maxInclusive 100000 ;\n                  sh:message \"A store holds 0..100000 l.\"@en ] ;\n    sh:property [ sh:path perma:holds ; sh:minCount 1 ; sh:node permash:InWaterKinds ;\n                  sh:message \"A water store says what it holds: concepts from perma:WaterKinds.\"@en ] ;\n    sh:property [ sh:path perma:overflowTo ; sh:maxCount 1 ; sh:class perma:WaterStore ] .\n\n# Worm liquid never into a store kept for clean water: either the valve's source holds no worm liquid, or\n# its target may hold it. (SHACL Core, so the cloud's validator and an edge's check the same.)\npermash:WormLiquidKeepsOut a sh:NodeShape ;\n    sh:not [ sh:property [ sh:path ( perma:flowFrom perma:holds ) ; sh:hasValue perma:WormLiquid ] ] .\npermash:TakesWormLiquid a sh:NodeShape ;\n    sh:property [ sh:path ( perma:flowTo perma:holds ) ; sh:hasValue perma:WormLiquid ] .\n\npermash:ValveShape a sh:NodeShape ;\n    sh:targetClass perma:Valve ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:maxCount 1 ; sh:message \"A valve needs a name.\"@en ] ;\n    sh:property [ sh:path perma:inGuild ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:Guild ;\n                  sh:message \"A valve belongs to one Perma5Guild.\"@en ] ;\n    sh:property [ sh:path perma:flowFrom ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:WaterStore ;\n                  sh:message \"A valve takes from one water store.\"@en ] ;\n    sh:property [ sh:path perma:flowTo ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:WaterStore ;\n                  sh:message \"A valve gives to one water store.\"@en ] ;\n    sh:property [ sh:path perma:valveKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InValveKinds ;\n                  sh:message \"A valve is a manual tap or an edge valve (perma:ValveKinds).\"@en ] ;\n    sh:or ( permash:WormLiquidKeepsOut permash:TakesWormLiquid ) ;\n    sh:message \"Worm liquid never flows into a store kept for clean water.\"@en .\n\n@prefix perma:   <https://permaculture.digitalhome.cloud/ontology#> .\n@prefix permash: <https://permaculture.digitalhome.cloud/shapes#> .\n@prefix sh:      <http://www.w3.org/ns/shacl#> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix sosa:    <http://www.w3.org/ns/sosa/> .\n\n# ============================================================\n# SHACL shapes for learning cycles in a habitat's A-Box, v0.1. Validate\n# TOGETHER with tbox/perma-learning-concepts.ttl and the habitat's shapes.\n# ============================================================\n\npermash:InCyclePhases a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:CyclePhases ] .\npermash:InVerdicts a sh:NodeShape ; sh:property [ sh:path skos:inScheme ; sh:hasValue perma:Verdicts ] .\n\npermash:LearningCycleShape a sh:NodeShape ;\n    sh:targetClass perma:LearningCycle ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:uniqueLang true ; sh:message \"A learning cycle needs a name (one per language).\"@en ] ;\n    sh:property [ sh:path perma:about ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;\n                  sh:message \"A learning cycle is about one guild or part.\"@en ] ;\n    sh:property [ sh:path perma:cyclePhase ; sh:minCount 1 ; sh:maxCount 1 ; sh:node permash:InCyclePhases ;\n                  sh:message \"A learning cycle stands in one phase of perma:CyclePhases.\"@en ] ;\n    sh:property [ sh:path perma:startedOn ; sh:maxCount 1 ; sh:datatype xsd:date ] ;\n    sh:property [ sh:path perma:endsOn ; sh:maxCount 1 ; sh:datatype xsd:date ] ;\n    sh:property [ sh:path perma:fromStarter ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path perma:hasHypothesis ; sh:class perma:Hypothesis ] .\n\npermash:HypothesisShape a sh:NodeShape ;\n    sh:targetClass perma:Hypothesis ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:uniqueLang true ; sh:message \"A hypothesis says what it claims (one text per language).\"@en ] ;\n    sh:property [ sh:path perma:code ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path perma:expected ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:decimal ;\n                  sh:lessThanOrEquals perma:high ; sh:message \"A hypothesis expects one number, at most its highest.\"@en ] ;\n    sh:property [ sh:path perma:low ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:decimal ;\n                  sh:lessThanOrEquals perma:expected ; sh:message \"Its lowest is at most the number expected.\"@en ] ;\n    sh:property [ sh:path perma:high ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:decimal ] ;\n    sh:property [ sh:path perma:unit ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;\n                  sh:message \"A hypothesis names its unit.\"@en ] ;\n    sh:property [ sh:path perma:source ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path perma:measuredBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:Measure ;\n                  sh:message \"A hypothesis is measured by one measure.\"@en ] ;\n    sh:property [ sh:path perma:verdict ; sh:maxCount 1 ; sh:node permash:InVerdicts ] ;\n    sh:property [ sh:path perma:actTaken ; sh:maxCount 1 ; sh:datatype xsd:string ] .\n\npermash:MeasureShape a sh:NodeShape ;\n    sh:targetClass perma:Measure ;\n    sh:property [ sh:path rdfs:label ; sh:minCount 1 ; sh:uniqueLang true ; sh:message \"A measure needs a name (one per language).\"@en ] ;\n    sh:property [ sh:path perma:code ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path perma:method ; sh:uniqueLang true ] ;\n    sh:property [ sh:path perma:everyDays ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ; sh:maxInclusive 366 ;\n                  sh:message \"A measure is taken every 1..366 days.\"@en ] ;\n    sh:property [ sh:path perma:reading ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[A-Za-z][A-Za-z0-9_.]*$\" ;\n                  sh:message \"An edge reading is a key like wormBin.sumpL.\"@en ] .\n\npermash:CheckShape a sh:NodeShape ;\n    sh:targetClass perma:Check ;\n    sh:property [ sh:path perma:ofHypothesis ; sh:minCount 1 ; sh:maxCount 1 ; sh:class perma:Hypothesis ;\n                  sh:message \"A check is of one hypothesis.\"@en ] ;\n    sh:property [ sh:path sosa:hasSimpleResult ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:decimal ;\n                  sh:message \"A check has one measured number.\"@en ] ;\n    sh:property [ sh:path sosa:resultTime ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:date ;\n                  sh:message \"A check has the day it was measured.\"@en ] ;\n    sh:property [ sh:path perma:checkedBy ; sh:maxCount 1 ; sh:in ( \"person\" \"edge\" ) ] .\n";
